import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, Area } from '../types';
import { LayoutDashboard, Plus, Briefcase, LogOut, Shield, ArrowLeftRight } from 'lucide-react';
import { NewRequestModal } from './NewRequestModal';
import { RequestDetailModal } from './RequestDetailModal';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { currentUser, logout, viewMode, setViewMode, activeRole, setActiveRole, setGlobalFilterArea, setSelectedRequestId } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const getInitials = (name: string) => name.substring(0, 2).toUpperCase();
  const isHybridUser = currentUser.role === UserRole.ADMIN && !!currentUser.area;

  const handleToggleProfile = () => {
    // Al cambiar de rol, cerramos cualquier detalle abierto para evitar acciones inconsistentes
    setSelectedRequestId(null);

    if (activeRole === UserRole.ADMIN) {
        setActiveRole(UserRole.HEAD);
        setGlobalFilterArea(currentUser.area as Area);
    } else {
        setActiveRole(UserRole.ADMIN);
        setGlobalFilterArea('ALL');
    }
  };

  const getRoleBadge = () => {
    if (isHybridUser) {
        return (
            <button 
                onClick={handleToggleProfile}
                className={`flex items-center gap-1.5 px-2 py-0.5 rounded-lg text-[9px] font-semibold border transition-all ${
                    activeRole === UserRole.ADMIN 
                    ? 'bg-red-50/50 text-red-500 border-red-100 hover:bg-red-100' 
                    : 'bg-indigo-50/50 text-indigo-500 border-indigo-100 hover:bg-indigo-100'
                }`}
            >
                <ArrowLeftRight size={10} />
                {activeRole === UserRole.ADMIN ? 'MODO ADMIN' : `JEFE ${currentUser.area?.toUpperCase()}`}
            </button>
        );
    }

    switch (currentUser.role) {
        case UserRole.SUPERADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-800 text-white font-medium border border-slate-900 tracking-wider">SUPERADMIN</span>;
        case UserRole.ADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-50 text-slate-500 font-semibold border border-slate-100 tracking-wider uppercase">ADMIN</span>;
        default: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-50 text-slate-400 font-semibold border border-slate-100 tracking-wider uppercase">{currentUser.role}</span>;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200/60 z-30 shrink-0 h-14 px-6 flex items-center justify-between">
        <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 pr-6 border-r border-slate-100">
                <div className="bg-slate-100 p-1.5 rounded-lg text-slate-500">
                    <LayoutDashboard size={18} />
                </div>
                <h1 className="text-sm font-bold tracking-tight text-slate-400 leading-none">SISREQ</h1>
            </div>

            <nav className="flex items-center gap-4">
                {currentUser.role === UserRole.SUPERADMIN ? (
                    <div className="flex bg-slate-100/50 p-1 rounded-lg gap-1 border border-slate-200/50">
                        <button onClick={() => setViewMode('work')} className={`px-3 py-1 rounded-md transition-all text-[11px] ${viewMode === 'work' ? 'bg-white text-indigo-600 shadow-sm font-semibold' : 'text-slate-400 hover:text-slate-600'}`}>
                            Tablero
                        </button>
                        <button onClick={() => setViewMode('superadmin')} className={`px-3 py-1 rounded-md transition-all text-[11px] ${viewMode === 'superadmin' ? 'bg-slate-700 text-white shadow-sm font-semibold' : 'text-slate-400 hover:text-slate-600'}`}>
                            Master
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2 text-slate-400">
                        {activeRole === UserRole.ADMIN ? <Shield size={14}/> : <Briefcase size={14}/>}
                        <span className="text-[11px] font-semibold uppercase tracking-tight">
                            {activeRole === UserRole.ADMIN ? 'Consola Central' : `${activeRole} ${currentUser.area || ''}`}
                        </span>
                    </div>
                )}
            </nav>
        </div>

        <div className="flex items-center gap-4">
            {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) && (
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-1.5 rounded-lg flex items-center gap-2 text-[11px] font-semibold transition-all shadow-sm active:scale-95"
                >
                    <Plus size={14} /> 
                    <span className="uppercase">Nuevo Ticket</span>
                </button>
            )}

            <div className="h-6 w-px bg-slate-100 mx-1"></div>

            <div className="flex items-center gap-3">
                <div className="flex flex-col items-end">
                    <span className="text-[12px] font-semibold text-slate-600 leading-none mb-1">{currentUser.name}</span>
                    {getRoleBadge()}
                </div>
                <div className="w-8 h-8 rounded-lg bg-slate-50 border border-slate-100 flex items-center justify-center font-semibold text-[10px] text-slate-500 shrink-0">
                    {getInitials(currentUser.name)}
                </div>
                <button onClick={logout} className="p-1.5 text-slate-300 hover:text-red-400 transition-colors" title="Salir">
                    <LogOut size={18} />
                </button>
            </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 relative">
        {children}
        <div className="absolute inset-0 opacity-[0.2] pointer-events-none" 
             style={{backgroundImage: 'radial-gradient(#cbd5e1 1px, transparent 1px)', backgroundSize: '40px 40px'}}>
        </div>
      </main>

      <NewRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <RequestDetailModal />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { 
  X as LucideX, 
  UserPlus as LucideUserPlus, 
  User as LucideUser, 
  Building as LucideBuilding, 
  Lock as LucideLock, 
  Mail as LucideMail, 
  Shield as LucideShield, 
  Check as LucideCheck, 
  Save as LucideSave, 
  Power as LucidePower,
  UserCheck,
  ShieldCheck,
  Calculator,
  Users,
  FileCheck,
  BadgeDollarSign,
  Globe,
  Hash
} from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null;
}

const AREA_CONFIG = {
  [Area.CONTABILIDAD]: { icon: <Calculator size={18} />, desc: 'Balances y Facturas' },
  [Area.RRHH]: { icon: <Users size={18} />, desc: 'Personal y Beneficios' },
  [Area.ACREDITACION]: { icon: <FileCheck size={18} />, desc: 'Certificaciones' },
  [Area.FINANZAS]: { icon: <BadgeDollarSign size={18} />, desc: 'Presupuestos y Flujos' },
  'NONE': { icon: <Globe size={18} />, desc: 'Acceso a todas las áreas' }
};

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');

  useEffect(() => {
    if (isOpen) {
        if (userToEdit) {
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword('');
        } else {
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea(Area.CONTABILIDAD);
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  const canHaveArea = role === UserRole.HEAD || role === UserRole.ANALYST || role === UserRole.ADMIN;

  const handleRoleChange = (newRole: UserRole) => {
    setRole(newRole);
    if (newRole === UserRole.SUPERADMIN) {
        setArea('NONE');
    } else if (canHaveArea && area === 'NONE' && (newRole === UserRole.HEAD || newRole === UserRole.ANALYST)) {
        setArea(Area.CONTABILIDAD);
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email || (!userToEdit && !password)) return;

    const finalArea = canHaveArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        const updatedUser: User = {
            ...userToEdit,
            name,
            email,
            role,
            area: finalArea,
            status,
            password: password.trim() ? password : userToEdit.password
        };
        updateUser(updatedUser);
    } else {
        addUser(name, email, role, password, finalArea);
    }
    onClose();
  };

  const isEditMode = !!userToEdit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity" onClick={onClose} />

      <div className="relative bg-white rounded-[2.5rem] shadow-[0_32px_80px_-20px_rgba(0,0,0,0.3)] w-full max-w-xl overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[10px] border-slate-800 flex flex-col max-h-[90vh]">

        <div className="bg-slate-50 border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-4">
             <div className="bg-slate-800 p-3 rounded-2xl text-white shadow-lg shadow-slate-200 shrink-0">
                {isEditMode ? <LucideUser size={22} strokeWidth={2.5}/> : <LucideUserPlus size={22} strokeWidth={2.5}/>}
             </div>
             <div>
                <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider shadow-sm ${isEditMode ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                        {isEditMode ? 'MODIFICAR PERFIL' : 'NUEVO ACCESO'}
                    </span>
                    <span className="flex items-center gap-1 text-[11px] text-slate-400 font-mono font-bold tracking-tighter bg-white/60 px-2 py-0.5 rounded-md border border-slate-100">
                        <Hash size={10}/>IDENTITY-SYS
                    </span>
                </div>
                <h2 className="text-xl font-bold text-slate-900 leading-tight tracking-tight">{isEditMode ? 'Gestión de Usuario' : 'Crear Colaborador'}</h2>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2.5 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm">
            <LucideX size={22} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
          <form id="user-form" onSubmit={handleSubmit} className="p-8 space-y-10">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <LucideUser size={14} className="text-slate-600" /> Nombre Completo
                    </label>
                    <input 
                        required 
                        autoFocus
                        className="w-full bg-slate-50 border-2 border-slate-100 text-slate-800 text-sm rounded-2xl px-5 py-4 focus:outline-none focus:ring-8 focus:ring-slate-500/5 focus:border-slate-800 transition-all font-semibold shadow-inner" 
                        value={name} 
                        onChange={e => setName(e.target.value)} 
                        placeholder="Juan Pérez..." 
                    />
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <LucideMail size={14} className="text-slate-600" /> E-mail Institucional
                    </label>
                    <input 
                        required 
                        type="email" 
                        className="w-full bg-slate-50 border-2 border-slate-100 text-slate-800 text-sm rounded-2xl px-5 py-4 focus:outline-none focus:ring-8 focus:ring-slate-500/5 focus:border-slate-800 transition-all font-semibold shadow-inner" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        placeholder="usuario@dominio.com" 
                    />
                </div>
            </div>

            <div className="space-y-4">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                    <LucideShield size={14} className="text-slate-600" /> Nivel de Privilegios
                </label>
                <div className="flex bg-slate-100 p-1.5 rounded-[1.5rem] gap-1.5 border border-slate-200">
                    {Object.values(UserRole).map(r => (
                        <button 
                            key={r}
                            type="button" 
                            onClick={() => handleRoleChange(r)} 
                            className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${role === r ? 'bg-slate-800 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                        >
                            {r}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-4">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                    <LucideBuilding size={14} className="text-slate-600" /> Adscripción Orgánica
                </label>
                <div className={`grid grid-cols-1 md:grid-cols-2 gap-3 transition-opacity duration-300 ${!canHaveArea ? 'opacity-30 pointer-events-none' : 'opacity-100'}`}>
                    {(role === UserRole.ADMIN || role === UserRole.SUPERADMIN) && (
                        <button
                            type="button"
                            onClick={() => setArea('NONE')}
                            className={`
                                relative flex items-center gap-4 p-4 rounded-2xl border-2 text-left transition-all duration-300 group
                                ${area === 'NONE' 
                                ? 'border-indigo-600 bg-indigo-50/50 shadow-md' 
                                : 'border-slate-100 bg-slate-50/30 hover:border-slate-200 hover:bg-slate-50'}
                            `}
                        >
                            <div className={`p-2.5 rounded-xl transition-all ${area === 'NONE' ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>
                                {AREA_CONFIG.NONE.icon}
                            </div>
                            <div className="min-w-0">
                                <div className={`text-[13px] font-bold tracking-tight ${area === 'NONE' ? 'text-indigo-900' : 'text-slate-700'}`}>Acceso Global</div>
                                <div className="text-[9px] text-slate-500 font-medium">{AREA_CONFIG.NONE.desc}</div>
                            </div>
                        </button>
                    )}
                    {Object.values(Area).map((a) => {
                        const config = AREA_CONFIG[a];
                        const isSelected = area === a;
                        return (
                            <button
                                key={a}
                                type="button"
                                onClick={() => setArea(a)}
                                className={`
                                    relative flex items-center gap-4 p-4 rounded-2xl border-2 text-left transition-all duration-300 group
                                    ${isSelected 
                                    ? 'border-indigo-600 bg-indigo-50/50 shadow-md' 
                                    : 'border-slate-100 bg-slate-50/30 hover:border-slate-200 hover:bg-slate-50'}
                                `}
                            >
                                <div className={`p-2.5 rounded-xl transition-all ${isSelected ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-white text-slate-400 border border-slate-100'}`}>
                                    {config.icon}
                                </div>
                                <div className="min-w-0">
                                    <div className={`text-[13px] font-bold tracking-tight ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{a}</div>
                                    <div className="text-[9px] text-slate-500 font-medium">{config.desc}</div>
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6 border-t border-slate-100">
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <LucideLock size={14} className="text-slate-600" /> Credencial de Acceso
                    </label>
                    <input 
                        type="password" 
                        className="w-full bg-slate-50 border-2 border-slate-100 text-slate-800 text-sm rounded-2xl px-5 py-4 focus:outline-none focus:ring-8 focus:ring-slate-500/5 focus:border-slate-800 transition-all font-bold tracking-widest shadow-inner" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        placeholder={isEditMode ? "********" : "••••"} 
                    />
                </div>

                {isEditMode && (
                    <div className="space-y-4">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                            <LucidePower size={14} className="text-slate-600" /> Control de Estado
                        </label>
                        <div className="flex bg-slate-100 p-1.5 rounded-[1.5rem] gap-1.5 border border-slate-200">
                            <button 
                                type="button" 
                                onClick={() => setStatus('ACTIVE')} 
                                className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${status === 'ACTIVE' ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                            >
                                Activo
                            </button>
                            <button 
                                type="button" 
                                onClick={() => setStatus('INACTIVE')} 
                                className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${status === 'INACTIVE' ? 'bg-slate-400 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                            >
                                Inactivo
                            </button>
                        </div>
                    </div>
                )}
            </div>
          </form>
        </div>

        <div className="bg-white border-t border-slate-100 p-6 flex items-center justify-between gap-4 shrink-0 z-20">
            <button 
                type="button" 
                onClick={onClose} 
                className="px-6 py-3.5 text-slate-400 font-bold text-[11px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all"
            >
                Cerrar
            </button>
            <button 
                form="user-form"
                type="submit" 
                className="bg-slate-800 hover:bg-slate-900 text-white py-4 px-10 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-slate-200 flex items-center gap-3 transition-all active:scale-95"
            >
                {isEditMode ? <LucideSave size={18}/> : <ShieldCheck size={18} />} 
                {isEditMode ? 'Actualizar Registro' : 'Registrar Colaborador'}
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area, Priority } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    if (activeRole === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;
    if (!hasAccess) return false;
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;
    let isValidMove = false;
    if (currentUser.role === UserRole.SUPERADMIN) isValidMove = true;
    else {
        if (activeRole === UserRole.ADMIN && currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        if (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) {
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                if (activeRole === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }
    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-600 bg-white border-indigo-100', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-600 bg-white border-orange-100', bodyTint: 'bg-orange-50/10' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-600 bg-white border-amber-100', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-600 bg-white border-emerald-100', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Monitor Maestro";
    if (activeRole === UserRole.ADMIN) return "Administración Central";
    if (activeRole === UserRole.HEAD) return `Unidad ${currentUser.area}`;
    return `Operaciones ${currentUser.area}`;
  };

  const getPriorityBadgeClass = (priority: Priority) => {
    switch(priority) {
      case Priority.HIGH: return 'bg-red-50 text-red-600 border-red-100';
      case Priority.MEDIUM: return 'bg-amber-50 text-amber-600 border-amber-200';
      case Priority.LOW: return 'bg-slate-50 text-slate-500 border-slate-200';
      default: return 'bg-slate-50 text-slate-500 border-slate-200';
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F1F5F9]">
      <div className="px-8 py-3.5 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-[12px] font-bold text-slate-400 uppercase tracking-widest leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded-md text-[9px] font-bold border border-indigo-100">
                {filteredRequests.length} TICKETS
             </span>
          </div>

          <div className="flex items-center gap-3">
             <div className="relative min-w-[240px]">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar ticket..." 
                    className="w-full pl-9 pr-3 py-1.5 text-[11px] font-medium bg-slate-50 border border-slate-200 rounded-lg focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[160px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-3 pr-8 py-1.5 text-[11px] font-semibold bg-white border border-slate-200 rounded-lg appearance-none cursor-pointer outline-none hover:border-indigo-300 transition-all text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300"><ChevronDown size={12} /></div>
                 </div>
             )}

             <div className="flex bg-slate-100 p-1 rounded-lg gap-1 border border-slate-200">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Tablero"><LayoutGrid size={14} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Listado"><List size={14} /></button>
             </div>
          </div>
      </div>

      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
            <div className="h-full flex px-6 py-6 gap-6 min-w-[1200px]">
                {COLUMNS_CONFIG.map((col) => {
                    if ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && col.status === Status.RECIBIDO && currentUser.role !== UserRole.SUPERADMIN) return null;
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;
                    return (
                        <div 
                            key={col.status} 
                            className={`
                                flex-1 flex flex-col min-w-[280px] max-w-[340px] transition-all duration-300 rounded-2xl border 
                                ${isOver ? 'bg-indigo-50 border-indigo-300 border-dashed ring-4 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                            `} 
                            onDragOver={(e) => handleDragOver(e, col.status)} 
                            onDragLeave={handleDragLeave} 
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between px-4 py-3 mx-2 mt-2 rounded-xl border shadow-sm shrink-0 font-semibold text-[11px] uppercase tracking-wider ${col.headerColor}`}>
                                <div className="flex items-center gap-2.5">{col.icon}{col.title}</div>
                                <span className="bg-slate-50 border border-slate-100 px-2 py-0.5 rounded-md text-[10px] text-slate-500">{items.length}</span>
                            </div>

                            <div className="flex-1 overflow-y-auto px-2 pb-6 custom-scrollbar flex flex-col gap-1 mt-3">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[160px] border-2 border-dashed rounded-2xl flex flex-col gap-3 items-center justify-center text-slate-300 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-200 bg-white/50' : 'border-slate-200/30'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-[9px] font-semibold uppercase tracking-widest opacity-40">{isOver ? 'SOLTAR' : 'SIN TICKETS'}</span>
                                    </div>
                                ) : (
                                    items.map(req => <RequestCard key={req.id} data={req} />)
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      ) : (
          <div className="flex-1 overflow-hidden px-8 py-8">
              <div className="h-full flex flex-col bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
                <div className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-10 py-4 bg-slate-50/50 border-b border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                    <div>ID</div><div>Prioridad</div><div>Estado</div><div>Asunto</div><div>Solicitante</div><div>Área</div><div className="text-right">Fecha</div>
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1 p-2">
                    {filteredRequests.map(req => (
                        <div key={req.id} onClick={() => setSelectedRequestId(req.id)} className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-8 py-3.5 bg-white hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-100 cursor-pointer transition-all mb-1 items-center text-xs group">
                            <div className="font-mono text-[10px] text-slate-400 font-medium">#{req.id.split('-')[1].substring(0,6)}</div>
                            <div>
                              <span className={`text-[9px] font-semibold px-2 py-0.5 rounded-md border tracking-wider ${getPriorityBadgeClass(req.priority)}`}>
                                {req.priority.toUpperCase()}
                              </span>
                            </div>
                            <div><span className={`inline-block px-2 py-0.5 rounded-md text-[9px] font-semibold uppercase tracking-wider ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span></div>
                            <div className="font-semibold text-slate-700 truncate group-hover:text-indigo-600 transition-colors uppercase tracking-tight">{req.title}</div>
                            <div className="text-[10px] font-medium text-slate-500 truncate uppercase">{req.requester}</div>
                            <div className="text-[10px] font-bold text-indigo-400 truncate uppercase">{req.area}</div>
                            <div className="text-right text-[10px] text-slate-400 font-mono">{new Date(req.createdAt).toLocaleDateString()}</div>
                        </div>
                    ))}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, 
    CheckCircle, Briefcase, Pencil, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Circle, Eye, Hash
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => setSelectedRequestId(null);

  const getStatusTheme = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: 
            return { border: 'border-indigo-500', bg: 'bg-indigo-50/50', iconBg: 'bg-indigo-600', iconColor: 'text-indigo-600' };
        case Status.DERIVACION: 
            return { border: 'border-orange-500', bg: 'bg-orange-50/50', iconBg: 'bg-orange-600', iconColor: 'text-orange-600' };
        case Status.EJECUCION: 
            return { border: 'border-amber-500', bg: 'bg-amber-50/50', iconBg: 'bg-amber-600', iconColor: 'text-amber-600' };
        case Status.FINALIZADO: 
            return { border: 'border-emerald-500', bg: 'bg-emerald-50/50', iconBg: 'bg-emerald-600', iconColor: 'text-emerald-600' };
        default: 
            return { border: 'border-slate-500', bg: 'bg-slate-50/50', iconBg: 'bg-slate-600', iconColor: 'text-slate-600' };
    }
  };

  const theme = getStatusTheme(data.status);

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `Nota: ${newComment}`);
          setNewComment('');
      }
  }

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => updateStatus(data.id, Status.EJECUCION);

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const getTimelineConfig = (msg: string) => {
    const lower = msg.toLowerCase();
    if (lower.includes('devuelto') || lower.includes('devolución')) return { bg: 'bg-red-50', text: 'text-red-600', border: 'border-red-100', icon: <RotateCcw size={12} strokeWidth={2.5} /> };
    if (lower.includes('finalizado')) return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: <CheckCircle2 size={12} strokeWidth={2.5} /> };
    if (lower.includes('nota:')) return { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100', icon: <MessageSquare size={12} strokeWidth={2.5} /> };
    if (lower.includes('derivado')) return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100', icon: <ArrowRight size={12} strokeWidth={2.5} /> };
    if (lower.includes('creado') || lower.includes('ingresado')) return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: <Sparkles size={12} strokeWidth={2.5} /> };
    return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100', icon: <Circle size={10} strokeWidth={2.5} /> };
  };

  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const canEdit = isSuperAdmin || 
                  (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) || 
                  ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  const canComment = isSuperAdmin || 
                     (activeRole === UserRole.ADMIN && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  // Se expande la búsqueda a ANALYST y HEAD del mismo área
  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    u.status !== 'INACTIVE'
  );

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2.5rem] shadow-[0_32px_80px_-20px_rgba(0,0,0,0.3)] w-full max-w-xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[10px] ${theme.border}`}>

        <div className={`${theme.bg} border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0`}>
          <div className="flex items-center gap-4 min-w-0">
             <div className={`${theme.iconBg} p-3 rounded-2xl text-white shadow-lg shadow-indigo-100 shrink-0`}>
                <Eye size={22} strokeWidth={2.5} />
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="flex items-center gap-1 text-[11px] text-slate-400 font-mono font-bold tracking-tighter bg-white/60 px-2 py-0.5 rounded-md border border-slate-100">
                        <Hash size={10}/>{data.id.split('-')[1]}
                    </span>
                    {data.isReturned && <span className="flex items-center gap-1 text-[10px] bg-red-600 text-white px-2 py-1 rounded-lg font-bold uppercase tracking-wider animate-pulse shadow-md shadow-red-100"><AlertCircle size={10} /> REVISIÓN</span>}
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={(e) => setEditTitle(e.target.value)} className="w-full text-lg font-bold text-slate-800 bg-white border-2 border-indigo-200 rounded-xl px-3 py-1 outline-none focus:ring-4 focus:ring-indigo-500/10" autoFocus />
                ) : (
                    <h2 className="text-xl font-bold text-slate-900 leading-tight tracking-tight">{data.title}</h2>
                )}
             </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isEditing && canEdit && <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-2.5 rounded-xl hover:bg-white transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm"><Pencil size={18}/></button>}
            <button onClick={handleClose} className="p-2.5 text-slate-400 hover:text-slate-600 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm">
                <X size={22} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
            <div className="p-8 space-y-8">
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <Tag size={14} className={theme.iconColor}/> Especificación Técnica
                    </label>
                    {isEditing ? (
                        <div className="space-y-4 animate-in fade-in duration-300">
                             <textarea value={editDetail} onChange={(e) => setEditDetail(e.target.value)} className="w-full h-40 bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-[14px] text-slate-700 outline-none resize-none font-medium leading-relaxed shadow-inner focus:border-indigo-400 transition-all" />
                             <div className="flex justify-end gap-3">
                                <button onClick={handleCancelEdit} className="px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl text-[11px] font-bold uppercase tracking-wider transition-all">Cancelar</button>
                                <button onClick={handleSaveEdit} className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-xl shadow-indigo-100 text-[11px] font-bold flex items-center gap-2 uppercase tracking-wider transition-all"><Save size={14}/> Guardar Cambios</button>
                             </div>
                        </div>
                    ) : (
                        <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 text-[15px] font-normal text-slate-700 leading-relaxed whitespace-pre-wrap shadow-inner italic">
                            "{data.detail}"
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><User size={10}/></div> Solicitante
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Building size={10}/></div> Área Destino
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{data.area}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Calendar size={10}/></div> Fecha Ingreso
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{new Date(data.createdAt).toLocaleDateString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><AlertCircle size={10}/></div> Prioridad
                        </div>
                        <div className={`text-[14px] font-bold uppercase tracking-tight ${data.priority === 'Alta' ? 'text-red-500' : 'text-slate-700'}`}>{data.priority}</div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                    <div className="bg-indigo-600 p-5 rounded-3xl border border-indigo-700 flex items-center gap-5 animate-in fade-in slide-in-from-left-4 shadow-xl shadow-indigo-100">
                        <div className="w-12 h-12 rounded-2xl bg-white text-indigo-600 flex items-center justify-center text-sm font-bold shadow-lg">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div className="min-w-0">
                            <div className="text-[9px] text-indigo-100 font-bold uppercase tracking-[0.2em] mb-0.5 opacity-80">Responsable de Gestión</div>
                            <div className="text-base font-bold text-white truncate uppercase tracking-tight">{data.assignedAnalyst}</div>
                        </div>
                    </div>
                )}

                <div className="space-y-8 pt-6 border-t border-slate-100">
                    {canComment && (
                        <div className="space-y-4">
                            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                                <MessageSquare size={14} className={theme.iconColor}/> Bitácora de Seguimiento
                            </label>
                            <div className="relative group">
                                <textarea 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    className="w-full text-xs p-5 border-2 border-slate-100 rounded-3xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 bg-slate-50 pr-16 resize-none outline-none font-semibold transition-all shadow-inner" 
                                    placeholder="Registrar nueva nota operativa..." 
                                    rows={2} 
                                />
                                <button 
                                    onClick={handleAddComment} 
                                    disabled={!newComment.trim()} 
                                    className="absolute right-4 bottom-4 p-3 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 disabled:opacity-30 transition-all active:scale-95 shadow-xl shadow-indigo-100"
                                >
                                    <Send size={18} strokeWidth={2.5}/>
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="space-y-6">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                            <Clock size={14} className={theme.iconColor}/> Historial de Eventos
                        </label>
                        <div className="space-y-5 relative before:absolute before:left-[11px] before:top-2 before:bottom-2 before:w-[2px] before:bg-slate-100">
                            {[...data.logs].reverse().map((log) => {
                                const config = getTimelineConfig(log.message);
                                return (
                                    <div key={log.id} className="flex gap-5 relative z-10 group">
                                        <div className={`shrink-0 w-6 h-6 rounded-lg border-2 shadow-sm flex items-center justify-center ${config.bg} ${config.text} ${config.border} bg-white transition-all group-hover:scale-110`}>
                                            {config.icon}
                                        </div>
                                        <div className="flex-1 min-w-0 bg-slate-50/50 p-4 rounded-2xl border border-slate-100/50 group-hover:bg-white group-hover:border-slate-200 group-hover:shadow-md transition-all">
                                            <div className="flex items-center justify-between mb-1.5">
                                                <span className="text-[10px] font-bold text-slate-800 uppercase tracking-wider">{log.actor}</span>
                                                <span className="text-[9px] text-slate-400 font-mono font-bold bg-white px-2 py-0.5 rounded border border-slate-100">{new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                            </div>
                                            <p className={`text-[12px] font-semibold leading-tight uppercase tracking-tight ${config.text}`}>{log.message}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white border-t border-slate-100 p-6 flex items-center justify-between gap-4 shrink-0 z-20">
             <button onClick={handleClose} className="px-6 py-3.5 text-slate-400 font-bold text-[11px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all">Cerrar</button>
            <div className="flex items-center gap-4">
                {activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO && (
                     <button onClick={handleDerive} className="flex items-center gap-3 bg-indigo-600 hover:bg-indigo-700 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-indigo-200 transition-all active:scale-95">
                        Procesar Derivación <ArrowRight size={18} strokeWidth={3}/>
                     </button>
                )}

                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-4">
                         {showReturnInput ? (
                             <div className="flex gap-3 items-center bg-red-50 p-2.5 rounded-2xl border-2 border-red-100 animate-in slide-in-from-right-10 shadow-lg">
                                <input className="w-48 text-[11px] p-3 border-2 border-red-200 rounded-xl outline-none font-bold uppercase tracking-tight placeholder:text-red-300 focus:border-red-500 transition-colors" placeholder="Motivo del rechazo..." value={returnReason} onChange={e => setReturnReason(e.target.value)} autoFocus />
                                <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-5 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg shadow-red-100">Enviar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-red-400 p-2 hover:bg-red-100 rounded-lg transition-all"><X size={20}/></button>
                             </div>
                         ) : <button onClick={() => setShowReturnInput(true)} className="px-6 py-4 text-red-500 hover:bg-red-50 border-2 border-transparent rounded-2xl text-[11px] font-bold uppercase tracking-widest transition-all">Devolver</button>}

                         {!showReturnInput && (
                            <>
                                <div className="relative">
                                    <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-white border-2 border-slate-100 text-slate-700 py-4 px-6 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-sm flex items-center gap-2.5 transition-all hover:border-indigo-400 hover:text-indigo-600">
                                      <User size={18}/> {data.assignedAnalyst ? 'Reasignar' : 'Asignar'}
                                    </button>
                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-5 w-64 bg-white rounded-3xl shadow-2xl border border-slate-200 p-2 animate-in slide-in-from-bottom-3 z-50">
                                             <p className="text-[10px] font-bold text-slate-400 uppercase px-4 py-3 tracking-widest border-b border-slate-100 mb-2 flex items-center gap-3"><Briefcase size={12}/> Personal Habilitado</p>
                                             <div className="max-h-56 overflow-y-auto flex flex-col gap-1.5 custom-scrollbar">
                                                {availableAssignees.map(a => (
                                                  <button 
                                                    key={a.id} 
                                                    onClick={() => handleAssignAnalyst(a.name)} 
                                                    className="flex items-center gap-3 w-full text-left px-3 py-3 hover:bg-indigo-50 rounded-xl text-[11px] font-bold text-slate-700 transition-colors uppercase tracking-tight"
                                                  >
                                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-[10px] font-bold shadow-sm ${a.role === UserRole.HEAD ? 'bg-indigo-600 text-white' : 'bg-indigo-100 text-indigo-600'}`}>
                                                      {a.name.substring(0,2).toUpperCase()}
                                                    </div>
                                                    <div className="flex flex-col">
                                                      <span>{a.name}</span>
                                                      <span className="text-[8px] opacity-50">{a.role}</span>
                                                    </div>
                                                  </button>
                                                ))}
                                                {availableAssignees.length === 0 && <p className="text-[11px] text-slate-400 p-5 text-center italic font-bold">Sin personal disponible</p>}
                                             </div>
                                        </div>
                                    )}
                                </div>
                                <button onClick={handleStartExecution} className="bg-amber-500 hover:bg-amber-600 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-amber-100 flex items-center gap-2.5 transition-all active:scale-95">
                                    <Briefcase size={20} strokeWidth={2.5}/> Iniciar Gestión
                                </button>
                            </>
                         )}
                    </div>
                )}

                {(activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={handleFinalize} className="bg-emerald-600 hover:bg-emerald-700 text-white py-4 px-10 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-emerald-100 flex items-center gap-2.5 transition-all active:scale-95">
                        <CheckCircle size={20} strokeWidth={2.5}/> Finalizar Gestión
                     </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2 } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isAdmin = activeRole === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = activeRole === UserRole.HEAD;
  const isAnalyst = activeRole === UserRole.ANALYST;

  const isDraggable = () => {
    if (isSuperAdmin) return true;
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    if (isHead && data.area === currentUser.area) {
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    if (isAnalyst && data.area === currentUser.area) {
        if (data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-300';
    }
  };

  const priorityStyles = {
    'Alta': 'bg-red-50 text-red-600 border-red-100',
    'Media': 'bg-amber-50 text-amber-600 border-amber-200',
    'Baja': 'bg-slate-50 text-slate-500 border-slate-200'
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-2.5 relative group
            transition-all duration-200 ease-out
            shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_16px_-8px_rgba(0,0,0,0.08)]
            border border-slate-100
            border-l-[4px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'active:scale-[0.98]' : 'hover:bg-slate-50/30'}
            ${isMinimized ? 'h-[56px] py-2 px-4' : 'h-[185px] p-4'}
        `}
    >
      {/* Header Info */}
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-2.5'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-0.5 -ml-1 text-slate-200 group-hover:text-indigo-400">
                    <GripVertical size={12} />
                </div>
            )}
            <div className="flex items-center gap-1.5">
                <span className="flex items-center gap-0.5 font-mono text-[9px] text-slate-400 font-medium uppercase tracking-tight">
                    <Hash size={9} className="opacity-30" /> {data.id.split('-')[1].substring(0, 6)}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[8px] bg-red-600 text-white px-1.5 py-0.5 rounded font-bold tracking-tight animate-pulse shadow-sm uppercase">
                        REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border shadow-none transition-colors uppercase tracking-tight ${priorityStyles[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1 text-slate-200 hover:text-slate-400 hover:bg-slate-50 rounded transition-all"
           >
               {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 pr-8' : 'flex flex-col'}`}>
        <h3 className={`font-semibold text-slate-700 leading-snug tracking-tight group-hover:text-indigo-500 transition-colors 
            ${isMinimized ? 'text-[11px] truncate flex-1' : 'text-[13px] mb-2 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/30 p-2.5 rounded-lg border border-slate-100/30 mb-3 overflow-hidden">
                <p className="text-[11px] text-slate-400 leading-normal line-clamp-2 font-normal italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {/* Refined Footer */}
      {!isMinimized ? (
          <div className="mt-auto pt-2 border-t border-slate-100/40 flex flex-col gap-1.5 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-[9px] font-semibold text-indigo-400 uppercase tracking-tight">
                        <MapPin size={10} className="opacity-50" /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[9px] font-medium text-slate-400 uppercase tracking-tight max-w-[140px]">
                        <Building2 size={10} className="opacity-30" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[8px] font-bold border border-indigo-100" title="Responsable">
                            <UserIcon size={9} className="opacity-50" />
                            <span className="truncate max-w-[60px]">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1 text-slate-300 font-mono text-[9px]">
                            <Clock size={10} className="opacity-30" />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          /* Minimized Meta (Floating) */
          <div className="absolute right-10 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-40">
              <span className="text-[9px] font-semibold text-slate-300 uppercase tracking-widest">{data.area}</span>
              <div className={`w-1 h-1 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-400' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area, Priority } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    if (activeRole === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;
    if (!hasAccess) return false;
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;
    let isValidMove = false;
    if (currentUser.role === UserRole.SUPERADMIN) isValidMove = true;
    else {
        if (activeRole === UserRole.ADMIN && currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        if (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) {
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                if (activeRole === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }
    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-600 bg-white border-indigo-100', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-600 bg-white border-orange-100', bodyTint: 'bg-orange-50/10' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-600 bg-white border-amber-100', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-600 bg-white border-emerald-100', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Monitor Maestro";
    if (activeRole === UserRole.ADMIN) return "Administración Central";
    if (activeRole === UserRole.HEAD) return `Unidad ${currentUser.area}`;
    return `Operaciones ${currentUser.area}`;
  };

  const getPriorityBadgeClass = (priority: Priority) => {
    switch(priority) {
      case Priority.HIGH: return 'bg-red-50 text-red-600 border-red-100';
      case Priority.MEDIUM: return 'bg-amber-50 text-amber-600 border-amber-200';
      case Priority.LOW: return 'bg-slate-50 text-slate-500 border-slate-200';
      default: return 'bg-slate-50 text-slate-500 border-slate-200';
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F1F5F9]">
      <div className="px-8 py-3.5 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-[12px] font-bold text-slate-400 uppercase tracking-widest leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded-md text-[9px] font-bold border border-indigo-100">
                {filteredRequests.length} TICKETS
             </span>
          </div>

          <div className="flex items-center gap-3">
             <div className="relative min-w-[240px]">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar ticket..." 
                    className="w-full pl-9 pr-3 py-1.5 text-[11px] font-medium bg-slate-50 border border-slate-200 rounded-lg focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[160px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-3 pr-8 py-1.5 text-[11px] font-semibold bg-white border border-slate-200 rounded-lg appearance-none cursor-pointer outline-none hover:border-indigo-300 transition-all text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300"><ChevronDown size={12} /></div>
                 </div>
             )}

             <div className="flex bg-slate-100 p-1 rounded-lg gap-1 border border-slate-200">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Tablero"><LayoutGrid size={14} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Listado"><List size={14} /></button>
             </div>
          </div>
      </div>

      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
            <div className="h-full flex px-6 py-6 gap-6 min-w-[1200px]">
                {COLUMNS_CONFIG.map((col) => {
                    if ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && col.status === Status.RECIBIDO && currentUser.role !== UserRole.SUPERADMIN) return null;
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;
                    return (
                        <div 
                            key={col.status} 
                            className={`
                                flex-1 flex flex-col min-w-[280px] max-w-[340px] transition-all duration-300 rounded-2xl border 
                                ${isOver ? 'bg-indigo-50 border-indigo-300 border-dashed ring-4 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                            `} 
                            onDragOver={(e) => handleDragOver(e, col.status)} 
                            onDragLeave={handleDragLeave} 
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between px-4 py-3 mx-2 mt-2 rounded-xl border shadow-sm shrink-0 font-semibold text-[11px] uppercase tracking-wider ${col.headerColor}`}>
                                <div className="flex items-center gap-2.5">{col.icon}{col.title}</div>
                                <span className="bg-slate-50 border border-slate-100 px-2 py-0.5 rounded-md text-[10px] text-slate-500">{items.length}</span>
                            </div>

                            <div className="flex-1 overflow-y-auto px-2 pb-6 custom-scrollbar flex flex-col gap-1 mt-3">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[160px] border-2 border-dashed rounded-2xl flex flex-col gap-3 items-center justify-center text-slate-300 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-200 bg-white/50' : 'border-slate-200/30'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-[9px] font-semibold uppercase tracking-widest opacity-40">{isOver ? 'SOLTAR' : 'SIN TICKETS'}</span>
                                    </div>
                                ) : (
                                    items.map(req => <RequestCard key={req.id} data={req} />)
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      ) : (
          <div className="flex-1 overflow-hidden px-8 py-8">
              <div className="h-full flex flex-col bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
                <div className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-10 py-4 bg-slate-50/50 border-b border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                    <div>ID</div><div>Prioridad</div><div>Estado</div><div>Asunto</div><div>Solicitante</div><div>Área</div><div className="text-right">Fecha</div>
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1 p-2">
                    {filteredRequests.map(req => (
                        <div key={req.id} onClick={() => setSelectedRequestId(req.id)} className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-8 py-3.5 bg-white hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-100 cursor-pointer transition-all mb-1 items-center text-xs group">
                            <div className="font-mono text-[10px] text-slate-400 font-medium">#{req.id.split('-')[1].substring(0,6)}</div>
                            <div>
                              <span className={`text-[9px] font-bold px-2 py-0.5 rounded-md border tracking-wider ${getPriorityBadgeClass(req.priority)}`}>
                                {req.priority.toUpperCase()}
                              </span>
                            </div>
                            <div><span className={`inline-block px-2 py-0.5 rounded-md text-[9px] font-semibold uppercase tracking-wider ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span></div>
                            <div className="font-semibold text-slate-700 truncate group-hover:text-indigo-600 transition-colors uppercase tracking-tight">{req.title}</div>
                            <div className="text-[10px] font-medium text-slate-500 truncate uppercase tracking-tight">{req.requester}</div>
                            <div className="text-[10px] font-bold text-indigo-400 truncate uppercase tracking-tight">{req.area}</div>
                            <div className="text-right text-[10px] text-slate-400 font-mono">{new Date(req.createdAt).toLocaleDateString()}</div>
                        </div>
                    ))}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, UserStatus } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests);
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Error al inicializar la base de datos:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const handleSetViewMode = (mode: 'work' | 'superadmin') => {
    setViewMode(mode);
    setGlobalFilterArea('ALL'); // Resetear filtros al cambiar entre Master y Tablero
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
    await db.saveUser(updatedUser);
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: `u-${Date.now()}`,
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser) return;
    const newRequest: RequestCard = {
      id: `req-${Date.now()}`,
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: `log-${Date.now()}`,
        timestamp: new Date().toISOString(),
        message: `Requerimiento creado y registrado en bandeja de entrada`,
        actor: currentUser.name
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser]);

  const addLog = useCallback(async (id: string, message: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq = {
        ...req,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === newStatus) return;

    // Bloquear cambios si ya está finalizado (a menos que sea SuperAdmin)
    if (req.status === Status.FINALIZADO && currentUser.role !== UserRole.SUPERADMIN) return;

    let message = `Cambio de estado: ${req.status} -> ${newStatus}`;
    if (newStatus === Status.DERIVACION) message = `Derivado al área de ${req.area} para gestión de jefatura`;
    if (newStatus === Status.EJECUCION) message = `Iniciada la fase de ejecución por el responsable`;
    if (newStatus === Status.FINALIZADO) message = `Requerimiento completado satisfactoriamente`;

    const shouldClearAnalyst = newStatus === Status.RECIBIDO || newStatus === Status.DERIVACION;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
        isReturned: false,
        assignedAnalyst: shouldClearAnalyst ? undefined : req.assignedAnalyst,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: currentUser.role === UserRole.SUPERADMIN ? `[SISTEMA] ${message}` : message,
            actor: currentUser.name
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `DEVOLUCIÓN A BANDEJA: ${reason}`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return; // Protección

    const updatedReq = {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Analista asignado para ejecución: ${analystName}`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return; // Protección

    const updatedReq = {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Modificación de título/detalle por auditoría técnica`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  return (
    <SisreqContext.Provider value={{
      currentUser: currentUser!,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode: handleSetViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq debe ser usado dentro de un SisreqProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area, Priority } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

// Estilos centralizados para prioridades
export const PRIORITY_STYLES = {
  [Priority.HIGH]: 'bg-red-50 text-red-600 border-red-100',
  [Priority.MEDIUM]: 'bg-amber-50 text-amber-600 border-amber-200',
  [Priority.LOW]: 'bg-slate-50 text-slate-500 border-slate-200'
};

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    if (activeRole === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;
    if (!hasAccess) return false;
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    let isValidMove = false;
    if (currentUser.role === UserRole.SUPERADMIN) isValidMove = true;
    else {
        // Validación basada en ACTIVE ROLE
        if (activeRole === UserRole.ADMIN) {
            // Solo Administradores centrales pueden mover de Bandeja a Derivación
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        } else if (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) {
            const req = requests.find(r => r.id === requestId);
            // Solo Jefes/Analistas de su propia área pueden mover sus tickets
            if (req && req.area === currentUser.area) {
                if (activeRole === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }

    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-600 bg-white border-indigo-100', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-600 bg-white border-orange-100', bodyTint: 'bg-orange-50/10' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-600 bg-white border-amber-100', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-600 bg-white border-emerald-100', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Monitor Maestro";
    if (activeRole === UserRole.ADMIN) return "Administración Central";
    if (activeRole === UserRole.HEAD) return `Unidad ${currentUser.area}`;
    return `Operaciones ${currentUser.area}`;
  };

  return (
    <div className="flex flex-col h-full bg-[#F1F5F9]">
      <div className="px-8 py-3.5 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-[12px] font-bold text-slate-400 uppercase tracking-widest leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded-md text-[9px] font-bold border border-indigo-100">
                {filteredRequests.length} TICKETS
             </span>
          </div>

          <div className="flex items-center gap-3">
             <div className="relative min-w-[240px]">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar por ID, título o solicitante..." 
                    className="w-full pl-9 pr-3 py-1.5 text-[11px] font-medium bg-slate-50 border border-slate-200 rounded-lg focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[160px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-3 pr-8 py-1.5 text-[11px] font-semibold bg-white border border-slate-200 rounded-lg appearance-none cursor-pointer outline-none hover:border-indigo-300 transition-all text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300"><ChevronDown size={12} /></div>
                 </div>
             )}

             <div className="flex bg-slate-100 p-1 rounded-lg gap-1 border border-slate-200">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Tablero"><LayoutGrid size={14} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Listado"><List size={14} /></button>
             </div>
          </div>
      </div>

      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
            <div className="h-full flex px-6 py-6 gap-6 min-w-[1200px]">
                {COLUMNS_CONFIG.map((col) => {
                    // Solo Admin Central y SuperAdmin ven Bandeja
                    if ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && col.status === Status.RECIBIDO && currentUser.role !== UserRole.SUPERADMIN) return null;

                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;
                    return (
                        <div 
                            key={col.status} 
                            className={`
                                flex-1 flex flex-col min-w-[280px] max-w-[340px] transition-all duration-300 rounded-2xl border 
                                ${isOver ? 'bg-indigo-50 border-indigo-300 border-dashed ring-4 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                            `} 
                            onDragOver={(e) => handleDragOver(e, col.status)} 
                            onDragLeave={handleDragLeave} 
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between px-4 py-3 mx-2 mt-2 rounded-xl border shadow-sm shrink-0 font-semibold text-[11px] uppercase tracking-wider ${col.headerColor}`}>
                                <div className="flex items-center gap-2.5">{col.icon}{col.title}</div>
                                <span className="bg-slate-50 border border-slate-100 px-2 py-0.5 rounded-md text-[10px] text-slate-500">{items.length}</span>
                            </div>

                            <div className="flex-1 overflow-y-auto px-2 pb-6 custom-scrollbar flex flex-col gap-1 mt-3">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[160px] border-2 border-dashed rounded-2xl flex flex-col gap-3 items-center justify-center text-slate-300 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-200 bg-white/50' : 'border-slate-200/30'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-[9px] font-semibold uppercase tracking-widest opacity-40">{isOver ? 'SOLTAR' : 'SIN TICKETS'}</span>
                                    </div>
                                ) : (
                                    items.map(req => <RequestCard key={req.id} data={req} />)
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      ) : (
          <div className="flex-1 overflow-hidden px-8 py-8">
              <div className="h-full flex flex-col bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
                <div className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-10 py-4 bg-slate-50/50 border-b border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                    <div>ID</div><div>Prioridad</div><div>Estado</div><div>Asunto</div><div>Solicitante</div><div>Área</div><div className="text-right">Fecha</div>
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1 p-2">
                    {filteredRequests.map(req => (
                        <div key={req.id} onClick={() => setSelectedRequestId(req.id)} className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-8 py-3.5 bg-white hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-100 cursor-pointer transition-all mb-1 items-center text-xs group">
                            <div className="font-mono text-[10px] text-slate-400 font-medium">#{req.id.split('-')[1].substring(0,6)}</div>
                            <div>
                              <span className={`text-[9px] font-bold px-2 py-0.5 rounded-md border tracking-wider ${PRIORITY_STYLES[req.priority]}`}>
                                {req.priority}
                              </span>
                            </div>
                            <div><span className={`inline-block px-2 py-0.5 rounded-md text-[9px] font-semibold uppercase tracking-wider ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span></div>
                            <div className="font-semibold text-slate-700 truncate group-hover:text-indigo-600 transition-colors uppercase tracking-tight">{req.title}</div>
                            <div className="text-[10px] font-medium text-slate-500 truncate uppercase tracking-tight">{req.requester}</div>
                            <div className="text-[10px] font-bold text-indigo-400 truncate uppercase tracking-tight">{req.area}</div>
                            <div className="text-right text-[10px] text-slate-400 font-mono">{new Date(req.createdAt).toLocaleDateString()}</div>
                        </div>
                    ))}
                    {filteredRequests.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-20 text-slate-300 italic">
                            No se encontraron requerimientos que coincidan con la búsqueda.
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from './Board';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2 } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isAdmin = activeRole === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = activeRole === UserRole.HEAD;
  const isAnalyst = activeRole === UserRole.ANALYST;

  const isDraggable = () => {
    if (isSuperAdmin) return true;
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    // Jefes y Analistas solo pueden arrastrar de su propia área
    if (isHead && data.area === currentUser.area) {
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    if (isAnalyst && data.area === currentUser.area) {
        if (data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-2.5 relative group
            transition-all duration-200 ease-out
            shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_16px_-8px_rgba(0,0,0,0.08)]
            border border-slate-100
            border-l-[4px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'active:scale-[0.98]' : 'hover:bg-slate-50/30'}
            ${isMinimized ? 'h-[56px] py-2 px-4' : 'h-[185px] p-4'}
        `}
    >
      {/* Header Info */}
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-2.5'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-0.5 -ml-1 text-slate-200 group-hover:text-indigo-400">
                    <GripVertical size={12} />
                </div>
            )}
            <div className="flex items-center gap-1.5">
                <span className="flex items-center gap-0.5 font-mono text-[9px] text-slate-400 font-medium uppercase tracking-tight">
                    <Hash size={9} className="opacity-30" /> {data.id.split('-')[1].substring(0, 6)}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[8px] bg-red-600 text-white px-1.5 py-0.5 rounded font-bold tracking-tight animate-pulse shadow-sm uppercase">
                        REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border shadow-none transition-colors uppercase tracking-tight ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1 text-slate-200 hover:text-slate-400 hover:bg-slate-50 rounded transition-all"
           >
               {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 pr-8' : 'flex flex-col'}`}>
        <h3 className={`font-semibold text-slate-700 leading-snug tracking-tight group-hover:text-indigo-500 transition-colors 
            ${isMinimized ? 'text-[11px] truncate flex-1' : 'text-[13px] mb-2 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/30 p-2.5 rounded-lg border border-slate-100/30 mb-3 overflow-hidden">
                <p className="text-[11px] text-slate-400 leading-normal line-clamp-2 font-normal italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {/* Refined Footer */}
      {!isMinimized ? (
          <div className="mt-auto pt-2 border-t border-slate-100/40 flex flex-col gap-1.5 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-[9px] font-semibold text-indigo-400 uppercase tracking-tight">
                        <MapPin size={10} className="opacity-50" /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[9px] font-medium text-slate-400 uppercase tracking-tight max-w-[140px]">
                        <Building2 size={10} className="opacity-30" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[8px] font-bold border border-indigo-100" title="Responsable">
                            <UserIcon size={9} className="opacity-50" />
                            <span className="truncate max-w-[60px]">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1 text-slate-300 font-mono text-[9px]">
                            <Clock size={10} className="opacity-30" />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          /* Minimized Meta (Floating) */
          <div className="absolute right-10 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-40">
              <span className="text-[9px] font-semibold text-slate-300 uppercase tracking-widest">{data.area}</span>
              <div className={`w-1 h-1 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-400' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, 
    CheckCircle, Briefcase, Pencil, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Circle, Eye, Hash
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => setSelectedRequestId(null);

  const isFinalized = data.status === Status.FINALIZADO;

  const getStatusTheme = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: 
            return { border: 'border-indigo-500', bg: 'bg-indigo-50/50', iconBg: 'bg-indigo-600', iconColor: 'text-indigo-600' };
        case Status.DERIVACION: 
            return { border: 'border-orange-500', bg: 'bg-orange-50/50', iconBg: 'bg-orange-600', iconColor: 'text-orange-600' };
        case Status.EJECUCION: 
            return { border: 'border-amber-500', bg: 'bg-amber-50/50', iconBg: 'bg-amber-600', iconColor: 'text-amber-600' };
        case Status.FINALIZADO: 
            return { border: 'border-emerald-500', bg: 'bg-emerald-50/50', iconBg: 'bg-emerald-600', iconColor: 'text-emerald-600' };
        default: 
            return { border: 'border-slate-500', bg: 'bg-slate-50/50', iconBg: 'bg-slate-600', iconColor: 'text-slate-600' };
    }
  };

  const theme = getStatusTheme(data.status);

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `Nota: ${newComment}`);
          setNewComment('');
      }
  }

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => updateStatus(data.id, Status.EJECUCION);

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const getTimelineConfig = (msg: string) => {
    const lower = msg.toLowerCase();
    if (lower.includes('devuelto') || lower.includes('devolución')) return { bg: 'bg-red-50', text: 'text-red-600', border: 'border-red-100', icon: <RotateCcw size={12} strokeWidth={2.5} /> };
    if (lower.includes('finalizado')) return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: <CheckCircle2 size={12} strokeWidth={2.5} /> };
    if (lower.includes('nota:')) return { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100', icon: <MessageSquare size={12} strokeWidth={2.5} /> };
    if (lower.includes('derivado')) return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100', icon: <ArrowRight size={12} strokeWidth={2.5} /> };
    if (lower.includes('creado') || lower.includes('ingresado')) return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: <Sparkles size={12} strokeWidth={2.5} /> };
    return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100', icon: <Circle size={10} strokeWidth={2.5} /> };
  };

  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;

  // No se permite editar si está finalizado (excepto logs)
  const canEdit = !isFinalized && (isSuperAdmin || 
                  (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) || 
                  ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area));

  const canComment = isSuperAdmin || 
                     (activeRole === UserRole.ADMIN && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    u.status !== 'INACTIVE'
  );

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2.5rem] shadow-[0_32px_80px_-20px_rgba(0,0,0,0.3)] w-full max-w-xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[10px] ${theme.border}`}>

        <div className={`${theme.bg} border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0`}>
          <div className="flex items-center gap-4 min-w-0">
             <div className={`${theme.iconBg} p-3 rounded-2xl text-white shadow-lg shadow-indigo-100 shrink-0`}>
                <Eye size={22} strokeWidth={2.5} />
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="flex items-center gap-1 text-[11px] text-slate-400 font-mono font-bold tracking-tighter bg-white/60 px-2 py-0.5 rounded-md border border-slate-100">
                        <Hash size={10}/>{data.id.split('-')[1]}
                    </span>
                    {data.isReturned && <span className="flex items-center gap-1 text-[10px] bg-red-600 text-white px-2 py-1 rounded-lg font-bold uppercase tracking-wider animate-pulse shadow-md shadow-red-100"><AlertCircle size={10} /> REVISIÓN</span>}
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={(e) => setEditTitle(e.target.value)} className="w-full text-lg font-bold text-slate-800 bg-white border-2 border-indigo-200 rounded-xl px-3 py-1 outline-none focus:ring-4 focus:ring-indigo-500/10" autoFocus />
                ) : (
                    <h2 className="text-xl font-bold text-slate-900 leading-tight tracking-tight">{data.title}</h2>
                )}
             </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isEditing && canEdit && <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-2.5 rounded-xl hover:bg-white transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm"><Pencil size={18}/></button>}
            <button onClick={handleClose} className="p-2.5 text-slate-400 hover:text-slate-600 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm">
                <X size={22} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
            <div className="p-8 space-y-8">
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <Tag size={14} className={theme.iconColor}/> Especificación Técnica
                    </label>
                    {isEditing ? (
                        <div className="space-y-4 animate-in fade-in duration-300">
                             <textarea value={editDetail} onChange={(e) => setEditDetail(e.target.value)} className="w-full h-40 bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-[14px] text-slate-700 outline-none resize-none font-medium leading-relaxed shadow-inner focus:border-indigo-400 transition-all" />
                             <div className="flex justify-end gap-3">
                                <button onClick={handleCancelEdit} className="px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl text-[11px] font-bold uppercase tracking-wider transition-all">Cancelar</button>
                                <button onClick={handleSaveEdit} className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-xl shadow-indigo-100 text-[11px] font-bold flex items-center gap-2 uppercase tracking-wider transition-all"><Save size={14}/> Guardar Cambios</button>
                             </div>
                        </div>
                    ) : (
                        <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 text-[15px] font-normal text-slate-700 leading-relaxed whitespace-pre-wrap shadow-inner italic">
                            "{data.detail}"
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><User size={10}/></div> Solicitante
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Building size={10}/></div> Área Destino
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{data.area}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Calendar size={10}/></div> Fecha Ingreso
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{new Date(data.createdAt).toLocaleDateString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><AlertCircle size={10}/></div> Prioridad
                        </div>
                        <div className={`text-[14px] font-bold uppercase tracking-tight ${data.priority === 'Alta' ? 'text-red-500' : 'text-slate-700'}`}>{data.priority}</div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                    <div className="bg-indigo-600 p-5 rounded-3xl border border-indigo-700 flex items-center gap-5 animate-in fade-in slide-in-from-left-4 shadow-xl shadow-indigo-100">
                        <div className="w-12 h-12 rounded-2xl bg-white text-indigo-600 flex items-center justify-center text-sm font-bold shadow-lg">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div className="min-w-0">
                            <div className="text-[9px] text-indigo-100 font-bold uppercase tracking-[0.2em] mb-0.5 opacity-80">Responsable de Gestión</div>
                            <div className="text-base font-bold text-white truncate uppercase tracking-tight">{data.assignedAnalyst}</div>
                        </div>
                    </div>
                )}

                <div className="space-y-8 pt-6 border-t border-slate-100">
                    {canComment && (
                        <div className="space-y-4">
                            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                                <MessageSquare size={14} className={theme.iconColor}/> Bitácora de Seguimiento
                            </label>
                            <div className="relative group">
                                <textarea 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    className="w-full text-xs p-5 border-2 border-slate-100 rounded-3xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 bg-slate-50 pr-16 resize-none outline-none font-semibold transition-all shadow-inner" 
                                    placeholder="Registrar nueva nota operativa..." 
                                    rows={2} 
                                />
                                <button 
                                    onClick={handleAddComment} 
                                    disabled={!newComment.trim()} 
                                    className="absolute right-4 bottom-4 p-3 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 disabled:opacity-30 transition-all active:scale-95 shadow-xl shadow-indigo-100"
                                >
                                    <Send size={18} strokeWidth={2.5}/>
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="space-y-6">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                            <Clock size={14} className={theme.iconColor}/> Historial de Eventos
                        </label>
                        <div className="space-y-5 relative before:absolute before:left-[11px] before:top-2 before:bottom-2 before:w-[2px] before:bg-slate-100">
                            {[...data.logs].reverse().map((log) => {
                                const config = getTimelineConfig(log.message);
                                return (
                                    <div key={log.id} className="flex gap-5 relative z-10 group">
                                        <div className={`shrink-0 w-6 h-6 rounded-lg border-2 shadow-sm flex items-center justify-center ${config.bg} ${config.text} ${config.border} bg-white transition-all group-hover:scale-110`}>
                                            {config.icon}
                                        </div>
                                        <div className="flex-1 min-w-0 bg-slate-50/50 p-4 rounded-2xl border border-slate-100/50 group-hover:bg-white group-hover:border-slate-200 group-hover:shadow-md transition-all">
                                            <div className="flex items-center justify-between mb-1.5">
                                                <span className="text-[10px] font-bold text-slate-800 uppercase tracking-wider">{log.actor}</span>
                                                <span className="text-[9px] text-slate-400 font-mono font-bold bg-white px-2 py-0.5 rounded border border-slate-100">{new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                            </div>
                                            <p className={`text-[12px] font-semibold leading-tight uppercase tracking-tight ${config.text}`}>{log.message}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white border-t border-slate-100 p-6 flex items-center justify-between gap-4 shrink-0 z-20">
             <button onClick={handleClose} className="px-6 py-3.5 text-slate-400 font-bold text-[11px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all">Cerrar</button>
            <div className="flex items-center gap-4">
                {activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO && (
                     <button onClick={handleDerive} className="flex items-center gap-3 bg-indigo-600 hover:bg-indigo-700 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-indigo-200 transition-all active:scale-95">
                        Procesar Derivación <ArrowRight size={18} strokeWidth={3}/>
                     </button>
                )}

                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-4">
                         {showReturnInput ? (
                             <div className="flex gap-3 items-center bg-red-50 p-2.5 rounded-2xl border-2 border-red-100 animate-in slide-in-from-right-10 shadow-lg">
                                <input className="w-48 text-[11px] p-3 border-2 border-red-200 rounded-xl outline-none font-bold uppercase tracking-tight placeholder:text-red-300 focus:border-red-500 transition-colors" placeholder="Motivo del rechazo..." value={returnReason} onChange={e => setReturnReason(e.target.value)} autoFocus />
                                <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-5 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg shadow-red-100">Enviar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-red-400 p-2 hover:bg-red-100 rounded-lg transition-all"><X size={20}/></button>
                             </div>
                         ) : <button onClick={() => setShowReturnInput(true)} className="px-6 py-4 text-red-500 hover:bg-red-50 border-2 border-transparent rounded-2xl text-[11px] font-bold uppercase tracking-widest transition-all">Devolver</button>}

                         {!showReturnInput && (
                            <>
                                <div className="relative">
                                    <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-white border-2 border-slate-100 text-slate-700 py-4 px-6 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-sm flex items-center gap-2.5 transition-all hover:border-indigo-400 hover:text-indigo-600">
                                      <User size={18}/> {data.assignedAnalyst ? 'Reasignar' : 'Asignar'}
                                    </button>
                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-5 w-64 bg-white rounded-3xl shadow-2xl border border-slate-200 p-2 animate-in slide-in-from-bottom-3 z-50">
                                             <p className="text-[10px] font-bold text-slate-400 uppercase px-4 py-3 tracking-widest border-b border-slate-100 mb-2 flex items-center gap-3"><Briefcase size={12}/> Personal Habilitado</p>
                                             <div className="max-h-56 overflow-y-auto flex flex-col gap-1.5 custom-scrollbar">
                                                {availableAssignees.map(a => (
                                                  <button 
                                                    key={a.id} 
                                                    onClick={() => handleAssignAnalyst(a.name)} 
                                                    className="flex items-center gap-3 w-full text-left px-3 py-3 hover:bg-indigo-50 rounded-xl text-[11px] font-bold text-slate-700 transition-colors uppercase tracking-tight"
                                                  >
                                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-[10px] font-bold shadow-sm ${a.role === UserRole.HEAD ? 'bg-indigo-600 text-white' : 'bg-indigo-100 text-indigo-600'}`}>
                                                      {a.name.substring(0,2).toUpperCase()}
                                                    </div>
                                                    <div className="flex flex-col">
                                                      <span>{a.name}</span>
                                                      <span className="text-[8px] opacity-50">{a.role}</span>
                                                    </div>
                                                  </button>
                                                ))}
                                                {availableAssignees.length === 0 && <p className="text-[11px] text-slate-400 p-5 text-center italic font-bold">Sin personal disponible</p>}
                                             </div>
                                        </div>
                                    )}
                                </div>
                                <button onClick={handleStartExecution} className="bg-amber-500 hover:bg-amber-600 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-amber-100 flex items-center gap-2.5 transition-all active:scale-95">
                                    <Briefcase size={20} strokeWidth={2.5}/> Iniciar Gestión
                                </button>
                            </>
                         )}
                    </div>
                )}

                {!isFinalized && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={handleFinalize} className="bg-emerald-600 hover:bg-emerald-700 text-white py-4 px-10 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-emerald-100 flex items-center gap-2.5 transition-all active:scale-95">
                        <CheckCircle size={20} strokeWidth={2.5}/> Finalizar Gestión
                     </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, UserStatus } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

// Generador de ID único robusto
const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests);
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Error al inicializar la base de datos:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const handleSetViewMode = (mode: 'work' | 'superadmin') => {
    setViewMode(mode);
    setGlobalFilterArea('ALL');
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
    await db.saveUser(updatedUser);
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `Requerimiento creado y registrado en bandeja de entrada`,
        actor: currentUser.name
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser]);

  const addLog = useCallback(async (id: string, message: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq = {
        ...req,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === newStatus) return;

    if (req.status === Status.FINALIZADO && currentUser.role !== UserRole.SUPERADMIN) return;

    let message = `Cambio de estado: ${req.status} -> ${newStatus}`;
    if (newStatus === Status.DERIVACION) message = `Derivado al área de ${req.area} para gestión de jefatura`;
    if (newStatus === Status.EJECUCION) message = `Iniciada la fase de ejecución por el responsable`;
    if (newStatus === Status.FINALIZADO) message = `Requerimiento completado satisfactoriamente`;

    const shouldClearAnalyst = newStatus === Status.RECIBIDO || newStatus === Status.DERIVACION;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
        isReturned: false,
        assignedAnalyst: shouldClearAnalyst ? undefined : req.assignedAnalyst,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: currentUser.role === UserRole.SUPERADMIN ? `[SISTEMA] ${message}` : message,
            actor: currentUser.name
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `DEVOLUCIÓN A BANDEJA: ${reason}`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Analista asignado para ejecución: ${analystName}`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Modificación de título/detalle por auditoría técnica`,
            actor: currentUser.name
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests]);

  return (
    <SisreqContext.Provider value={{
      currentUser: currentUser!,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode: handleSetViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq debe ser usado dentro de un SisreqProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area, Priority } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

// Estilos centralizados para prioridades
export const PRIORITY_STYLES = {
  [Priority.HIGH]: 'bg-red-50 text-red-600 border-red-100',
  [Priority.MEDIUM]: 'bg-amber-50 text-amber-600 border-amber-200',
  [Priority.LOW]: 'bg-slate-50 text-slate-500 border-slate-200'
};

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    // SuperAdmin tiene acceso total sin importar el rol activo
    if (currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (activeRole === UserRole.ADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;

    if (!hasAccess) return false;

    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    let isValidMove = false;
    if (currentUser.role === UserRole.SUPERADMIN) isValidMove = true;
    else {
        // Validación basada en ACTIVE ROLE
        if (activeRole === UserRole.ADMIN) {
            // Solo Administradores centrales pueden mover de Bandeja a Derivación
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        } else if (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) {
            const req = requests.find(r => r.id === requestId);
            // Solo Jefes/Analistas de su propia área pueden mover sus tickets
            if (req && req.area === currentUser.area) {
                if (activeRole === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }

    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-600 bg-white border-indigo-100', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-600 bg-white border-orange-100', bodyTint: 'bg-orange-50/10' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-600 bg-white border-amber-100', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-600 bg-white border-emerald-100', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Monitor Maestro";
    if (activeRole === UserRole.ADMIN) return "Administración Central";
    if (activeRole === UserRole.HEAD) return `Unidad ${currentUser.area}`;
    return `Operaciones ${currentUser.area}`;
  };

  return (
    <div className="flex flex-col h-full bg-[#F1F5F9]">
      <div className="px-8 py-3.5 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-[12px] font-bold text-slate-400 uppercase tracking-widest leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded-md text-[9px] font-bold border border-indigo-100">
                {filteredRequests.length} TICKETS
             </span>
          </div>

          <div className="flex items-center gap-3">
             <div className="relative min-w-[280px]">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar por ID, título, origen o analista..." 
                    className="w-full pl-9 pr-3 py-1.5 text-[11px] font-medium bg-slate-50 border border-slate-200 rounded-lg focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[160px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-3 pr-8 py-1.5 text-[11px] font-semibold bg-white border border-slate-200 rounded-lg appearance-none cursor-pointer outline-none hover:border-indigo-300 transition-all text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300"><ChevronDown size={12} /></div>
                 </div>
             )}

             <div className="flex bg-slate-100 p-1 rounded-lg gap-1 border border-slate-200">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Tablero"><LayoutGrid size={14} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`} title="Listado"><List size={14} /></button>
             </div>
          </div>
      </div>

      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
            <div className="h-full flex px-6 py-6 gap-6 min-w-[1200px]">
                {COLUMNS_CONFIG.map((col) => {
                    // Visibilidad reforzada: SuperAdmin siempre ve Bandeja
                    if (currentUser.role !== UserRole.SUPERADMIN && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && col.status === Status.RECIBIDO) return null;

                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;
                    return (
                        <div 
                            key={col.status} 
                            className={`
                                flex-1 flex flex-col min-w-[280px] max-w-[340px] transition-all duration-300 rounded-2xl border 
                                ${isOver ? 'bg-indigo-50 border-indigo-300 border-dashed ring-4 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                            `} 
                            onDragOver={(e) => handleDragOver(e, col.status)} 
                            onDragLeave={handleDragLeave} 
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between px-4 py-3 mx-2 mt-2 rounded-xl border shadow-sm shrink-0 font-semibold text-[11px] uppercase tracking-wider ${col.headerColor}`}>
                                <div className="flex items-center gap-2.5">{col.icon}{col.title}</div>
                                <span className="bg-slate-50 border border-slate-100 px-2 py-0.5 rounded-md text-[10px] text-slate-500">{items.length}</span>
                            </div>

                            <div className="flex-1 overflow-y-auto px-2 pb-6 custom-scrollbar flex flex-col gap-1 mt-3">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[160px] border-2 border-dashed rounded-2xl flex flex-col gap-3 items-center justify-center text-slate-300 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-200 bg-white/50' : 'border-slate-200/30'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-[9px] font-semibold uppercase tracking-widest opacity-40">{isOver ? 'SOLTAR' : 'SIN TICKETS'}</span>
                                    </div>
                                ) : (
                                    items.map(req => <RequestCard key={req.id} data={req} />)
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      ) : (
          <div className="flex-1 overflow-hidden px-8 py-8">
              <div className="h-full flex flex-col bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
                <div className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-10 py-4 bg-slate-50/50 border-b border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                    <div>ID</div><div>Prioridad</div><div>Estado</div><div>Asunto</div><div>Solicitante</div><div>Área</div><div className="text-right">Fecha</div>
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1 p-2">
                    {filteredRequests.map(req => (
                        <div key={req.id} onClick={() => setSelectedRequestId(req.id)} className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-8 py-3.5 bg-white hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-100 cursor-pointer transition-all mb-1 items-center text-xs group">
                            <div className="font-mono text-[10px] text-slate-400 font-medium">#{req.id.split('-')[1].substring(0,6)}</div>
                            <div>
                              <span className={`text-[9px] font-bold px-2 py-0.5 rounded-md border tracking-wider ${PRIORITY_STYLES[req.priority]}`}>
                                {req.priority}
                              </span>
                            </div>
                            <div><span className={`inline-block px-2 py-0.5 rounded-md text-[9px] font-semibold uppercase tracking-wider ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span></div>
                            <div className="font-semibold text-slate-700 truncate group-hover:text-indigo-600 transition-colors uppercase tracking-tight">{req.title}</div>
                            <div className="text-[10px] font-medium text-slate-500 truncate uppercase tracking-tight">{req.requester}</div>
                            <div className="text-[10px] font-bold text-indigo-400 truncate uppercase tracking-tight">{req.area}</div>
                            <div className="text-right text-[10px] text-slate-400 font-mono">{new Date(req.createdAt).toLocaleDateString()}</div>
                        </div>
                    ))}
                    {filteredRequests.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-20 text-slate-300 italic">
                            No se encontraron requerimientos que coincidan con la búsqueda.
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

