            return { border: 'border-indigo-500', bg: 'bg-indigo-50/50', iconBg: 'bg-indigo-600', iconColor: 'text-indigo-600' };
        case Status.DERIVACION: 
            return { border: 'border-orange-500', bg: 'bg-orange-50/50', iconBg: 'bg-orange-600', iconColor: 'text-orange-600' };
        case Status.EJECUCION: 
            return { border: 'border-amber-500', bg: 'bg-amber-50/50', iconBg: 'bg-amber-600', iconColor: 'text-amber-600' };
        case Status.FINALIZADO: 
            return { border: 'border-emerald-500', bg: 'bg-emerald-50/50', iconBg: 'bg-emerald-600', iconColor: 'text-emerald-600' };
        default: 
            return { border: 'border-slate-500', bg: 'bg-slate-50/50', iconBg: 'bg-slate-600', iconColor: 'text-slate-600' };
    }
  };

  const theme = getStatusTheme(data.status);

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `Nota: ${newComment}`);
          setNewComment('');
      }
  }

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => updateStatus(data.id, Status.EJECUCION);

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const formatLogDate = (timestamp: string) => {
    const logDate = new Date(timestamp);
    const today = new Date();
    const isToday = logDate.toDateString() === today.toDateString();

    if (isToday) {
        return logDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return logDate.toLocaleDateString([], { day: '2-digit', month: '2-digit' }) + ' ' + 
           logDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getTimelineConfig = (msg: string) => {
    const lower = msg.toLowerCase();
    if (lower.includes('devuelto') || lower.includes('devolución')) return { bg: 'bg-red-50', text: 'text-red-600', border: 'border-red-100', icon: <RotateCcw size={12} strokeWidth={2.5} /> };
    if (lower.includes('finalizado')) return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: <CheckCircle2 size={12} strokeWidth={2.5} /> };
    if (lower.includes('nota:')) return { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100', icon: <MessageSquare size={12} strokeWidth={2.5} /> };
    if (lower.includes('derivado')) return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100', icon: <ArrowRight size={12} strokeWidth={2.5} /> };
    if (lower.includes('creado') || lower.includes('ingresado')) return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: <Sparkles size={12} strokeWidth={2.5} /> };
    return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100', icon: <Circle size={10} strokeWidth={2.5} /> };
  };

  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;

  const canEdit = !isFinalized && (isSuperAdmin || 
                  (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) || 
                  ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area));

  const canComment = isSuperAdmin || 
                     (activeRole === UserRole.ADMIN && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    u.status !== 'INACTIVE'
  );

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2.5rem] shadow-[0_32px_80px_-20px_rgba(0,0,0,0.3)] w-full max-w-xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[10px] ${theme.border}`}>

        <div className={`${theme.bg} border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0`}>
          <div className="flex items-center gap-4 min-w-0">
             <div className={`${theme.iconBg} p-3 rounded-2xl text-white shadow-lg shadow-indigo-100 shrink-0`}>
                <Eye size={22} strokeWidth={2.5} />
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="flex items-center gap-1 text-[11px] text-slate-400 font-mono font-bold tracking-tighter bg-white/60 px-2 py-0.5 rounded-md border border-slate-100">
                        <Hash size={10}/>{data.id.split('-')[1]}
                    </span>
                    {data.isReturned && <span className="flex items-center gap-1 text-[10px] bg-red-600 text-white px-2 py-1 rounded-lg font-bold uppercase tracking-wider animate-pulse shadow-md shadow-red-100"><AlertCircle size={10} /> REVISIÓN</span>}
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={(e) => setEditTitle(e.target.value)} className="w-full text-lg font-bold text-slate-800 bg-white border-2 border-indigo-200 rounded-xl px-3 py-1 outline-none focus:ring-4 focus:ring-indigo-500/10" autoFocus />
                ) : (
                    <h2 className="text-xl font-bold text-slate-900 leading-tight tracking-tight truncate">{data.title}</h2>
                )}
             </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isEditing && canEdit && <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-2.5 rounded-xl hover:bg-white transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm"><Pencil size={18}/></button>}
            <button onClick={handleClose} className="p-2.5 text-slate-400 hover:text-slate-600 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100 shadow-none hover:shadow-sm">
                <X size={22} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
            <div className="p-8 space-y-8">
                <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <Tag size={14} className={theme.iconColor}/> Especificación Técnica
                    </label>
                    {isEditing ? (
                        <div className="space-y-4 animate-in fade-in duration-300">
                             <textarea value={editDetail} onChange={(e) => setEditDetail(e.target.value)} className="w-full h-40 bg-slate-50 p-5 rounded-2xl border-2 border-slate-100 text-[14px] text-slate-700 outline-none resize-none font-medium leading-relaxed shadow-inner focus:border-indigo-400 transition-all" />
                             <div className="flex justify-end gap-3">
                                <button onClick={handleCancelEdit} className="px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-xl text-[11px] font-bold uppercase tracking-wider transition-all">Cancelar</button>
                                <button onClick={handleSaveEdit} className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-xl shadow-indigo-100 text-[11px] font-bold flex items-center gap-2 uppercase tracking-wider transition-all"><Save size={14}/> Guardar Cambios</button>
                             </div>
                        </div>
                    ) : (
                        <div className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100 text-[15px] font-normal text-slate-700 leading-relaxed whitespace-pre-wrap shadow-inner italic">
                            "{data.detail}"
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><User size={10}/></div> Solicitante
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight truncate">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Building size={10}/></div> Área Destino
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{data.area}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><Calendar size={10}/></div> Fecha Ingreso
                        </div>
                        <div className="text-[14px] font-bold text-slate-800 uppercase tracking-tight">{new Date(data.createdAt).toLocaleDateString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                        <div className="text-[9px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex items-center gap-2">
                            <div className="p-1 bg-indigo-50 text-indigo-500 rounded-md"><AlertCircle size={10}/></div> Prioridad
                        </div>
                        <div className={`text-[14px] font-bold uppercase tracking-tight ${data.priority === 'Alta' ? 'text-red-500' : 'text-slate-700'}`}>{data.priority}</div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                    <div className="bg-indigo-600 p-5 rounded-3xl border border-indigo-700 flex items-center gap-5 animate-in fade-in slide-in-from-left-4 shadow-xl shadow-indigo-100 group">
                        <div className="w-12 h-12 rounded-2xl bg-white text-indigo-600 flex items-center justify-center text-sm font-bold shadow-lg transition-transform group-hover:scale-110">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div className="min-w-0">
                            <div className="text-[9px] text-indigo-100 font-bold uppercase tracking-[0.2em] mb-0.5 opacity-80">Responsable de Gestión</div>
                            <div className="text-base font-bold text-white truncate uppercase tracking-tight" title={data.assignedAnalyst}>{data.assignedAnalyst}</div>
                        </div>
                    </div>
                )}

                <div className="space-y-8 pt-6 border-t border-slate-100">
                    {canComment && (
                        <div className="space-y-4">
                            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                                <MessageSquare size={14} className={theme.iconColor}/> Bitácora de Seguimiento
                            </label>
                            <div className="relative group">
                                <textarea 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    className="w-full text-xs p-5 border-2 border-slate-100 rounded-3xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 bg-slate-50 pr-16 resize-none outline-none font-semibold transition-all shadow-inner" 
                                    placeholder="Registrar nueva nota operativa..." 
                                    rows={2} 
                                />
                                <button 
                                    onClick={handleAddComment} 
                                    disabled={!newComment.trim()} 
                                    className="absolute right-4 bottom-4 p-3 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 disabled:opacity-30 transition-all active:scale-95 shadow-xl shadow-indigo-100"
                                >
                                    <Send size={18} strokeWidth={2.5}/>
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="space-y-6">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                            <Clock size={14} className={theme.iconColor}/> Historial de Eventos
                        </label>
                        <div className="space-y-5 relative before:absolute before:left-[11px] before:top-2 before:bottom-2 before:w-[2px] before:bg-slate-100">
                            {[...data.logs].reverse().map((log) => {
                                const config = getTimelineConfig(log.message);
                                return (
                                    <div key={log.id} className="flex gap-5 relative z-10 group">
                                        <div className={`shrink-0 w-6 h-6 rounded-lg border-2 shadow-sm flex items-center justify-center ${config.bg} ${config.text} ${config.border} bg-white transition-all group-hover:scale-110`}>
                                            {config.icon}
                                        </div>
                                        <div className="flex-1 min-w-0 bg-slate-50/50 p-4 rounded-2xl border border-slate-100/50 group-hover:bg-white group-hover:border-slate-200 group-hover:shadow-md transition-all">
                                            <div className="flex items-center justify-between mb-1.5">
                                                <span className="text-[10px] font-bold text-slate-800 uppercase tracking-wider">{log.actor}</span>
                                                <span className="text-[9px] text-slate-400 font-mono font-bold bg-white px-2 py-0.5 rounded border border-slate-100">
                                                    {formatLogDate(log.timestamp)}
                                                </span>
                                            </div>
                                            <p className={`text-[12px] font-semibold leading-tight uppercase tracking-tight ${config.text}`}>{log.message}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white border-t border-slate-100 p-6 flex items-center justify-between gap-4 shrink-0 z-20">
             <button onClick={handleClose} className="px-6 py-3.5 text-slate-400 font-bold text-[11px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all">Cerrar</button>
            <div className="flex items-center gap-4">
                {activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO && (
                     <button onClick={handleDerive} className="flex items-center gap-3 bg-indigo-600 hover:bg-indigo-700 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-indigo-200 transition-all active:scale-95">
                        Procesar Derivación <ArrowRight size={18} strokeWidth={3}/>
                     </button>
                )}

                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-4">
                         {showReturnInput ? (
                             <div className="flex gap-3 items-center bg-red-50 p-2.5 rounded-2xl border-2 border-red-100 animate-in slide-in-from-right-10 shadow-lg">
                                <input className="w-48 text-[11px] p-3 border-2 border-red-200 rounded-xl outline-none font-bold uppercase tracking-tight placeholder:text-red-300 focus:border-red-500 transition-colors" placeholder="Motivo del rechazo..." value={returnReason} onChange={e => setReturnReason(e.target.value)} autoFocus />
                                <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-5 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg shadow-red-100">Enviar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-red-400 p-2 hover:bg-red-100 rounded-lg transition-all"><X size={20}/></button>
                             </div>
                         ) : <button onClick={() => setShowReturnInput(true)} className="px-6 py-4 text-red-500 hover:bg-red-50 border-2 border-transparent rounded-2xl text-[11px] font-bold uppercase tracking-widest transition-all">Devolver</button>}

                         {!showReturnInput && (
                            <>
                                <div className="relative">
                                    <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-white border-2 border-slate-100 text-slate-700 py-4 px-6 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-sm flex items-center gap-2.5 transition-all hover:border-indigo-400 hover:text-indigo-600">
                                      <User size={18}/> {data.assignedAnalyst ? 'Reasignar' : 'Asignar'}
                                    </button>
                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-5 w-64 bg-white rounded-3xl shadow-2xl border border-slate-200 p-2 animate-in slide-in-from-bottom-3 z-50">
                                             <p className="text-[10px] font-bold text-slate-400 uppercase px-4 py-3 tracking-widest border-b border-slate-100 mb-2 flex items-center gap-3"><Briefcase size={12}/> Personal Habilitado</p>
                                             <div className="max-h-56 overflow-y-auto flex flex-col gap-1.5 custom-scrollbar">
                                                {availableAssignees.map(a => (
                                                  <button 
                                                    key={a.id} 
                                                    onClick={() => handleAssignAnalyst(a.name)} 
                                                    className="flex items-center gap-3 w-full text-left px-3 py-3 hover:bg-indigo-50 rounded-xl text-[11px] font-bold text-slate-700 transition-colors uppercase tracking-tight"
                                                  >
                                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-[10px] font-bold shadow-sm ${a.role === UserRole.HEAD ? 'bg-indigo-600 text-white' : 'bg-indigo-100 text-indigo-600'}`}>
                                                      {a.name.substring(0,2).toUpperCase()}
                                                    </div>
                                                    <div className="flex flex-col">
                                                      <span className="truncate">{a.name}</span>
                                                      <span className="text-[8px] opacity-50">{a.role}</span>
                                                    </div>
                                                  </button>
                                                ))}
                                                {availableAssignees.length === 0 && <p className="text-[11px] text-slate-400 p-5 text-center italic font-bold">Sin personal disponible</p>}
                                             </div>
                                        </div>
                                    )}
                                </div>
                                <button onClick={handleStartExecution} className="bg-amber-500 hover:bg-amber-600 text-white py-4 px-8 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-amber-100 flex items-center gap-2.5 transition-all active:scale-95">
                                    <Briefcase size={20} strokeWidth={2.5}/> Iniciar Gestión
                                </button>
                            </>
                         )}
                    </div>
                )}

                {!isFinalized && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={handleFinalize} className="bg-emerald-600 hover:bg-emerald-700 text-white py-4 px-10 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-2xl shadow-emerald-100 flex items-center gap-2.5 transition-all active:scale-95">
                        <CheckCircle size={20} strokeWidth={2.5}/> Finalizar Gestión
                     </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

