                )}

                {!isFinalized && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={handleFinalize} className="bg-emerald-600 hover:bg-emerald-700 text-white py-5 px-12 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-emerald-200 flex items-center gap-3 transition-all active:scale-95">
                        <CheckCircle size={22} strokeWidth={2.5}/> Finalizar Gestión de Ticket
                     </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Sparkles, AlertCircle } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'Control Maestro';
      case UserRole.ADMIN: return 'Administración Central';
      case UserRole.HEAD: return 'Jefaturas de Área';
      default: return 'Cuerpo Analista';
  }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-3.5 p-4 hover:bg-indigo-50/50 transition-all text-left group border-b border-slate-50 last:border-0"
    >
      <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-[11px] transition-all shadow-sm group-hover:scale-105 ${
          user.role === UserRole.SUPERADMIN ? 'bg-slate-900 text-white' :
          user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 group-hover:bg-red-100' :
          user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-100' :
          'bg-slate-100 text-slate-500 group-hover:bg-slate-200'
      }`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0">
          <div className="text-[13px] font-black text-slate-800 group-hover:text-indigo-600 truncate uppercase tracking-tight leading-none mb-1">{user.name}</div>
          <div className="text-[9px] text-slate-400 font-black uppercase tracking-widest truncate">{user.area || getRoleLabel(user.role)}</div>
      </div>
      {isSelected && <div className="bg-indigo-600 p-1.5 rounded-full text-white shadow-xl shadow-indigo-200"><Check size={14} strokeWidth={3}/></div>}
    </button>
);

