             </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isEditing && canEdit && <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-3 rounded-2xl hover:bg-white transition-all border border-transparent hover:border-slate-100 shadow-sm hover:shadow-md" title="Editar requerimiento"><Pencil size={20}/></button>}
