                                             <p className="text-[10px] font-black text-slate-400 uppercase px-5 py-4 tracking-[0.2em] border-b border-slate-100 mb-2 flex items-center gap-3"><Briefcase size={14}/> Nómina de {data.area}</p>
                                             <div className="max-h-64 overflow-y-auto flex flex-col gap-2 custom-scrollbar">
                                                {availableAssignees.map(a => (
