                                <button onClick={() => handleTransition(Status.EJECUCION, '¿Confirma el inicio de la ejecución técnica?')} className="bg-amber-500 hover:bg-amber-600 text-white py-5 px-10 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-amber-200 flex items-center gap-3 transition-all active:scale-95">
                                    <PlayCircle size={22} strokeWidth={2.5}/> Iniciar Labores
