                {!isFinalized && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={() => handleTransition(Status.FINALIZADO, '¿Declara el requerimiento como cumplido satisfactoriamente?')} className="bg-emerald-600 hover:bg-emerald-700 text-white py-5 px-12 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-emerald-200 flex items-center gap-3 transition-all active:scale-95">
