  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, UserStatus } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const generateId = (prefix: string) => `${prefix}-${Math.random().toString(36).substr(2, 6)}-${Date.now().toString(36)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests);
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Critical Failure in SISREQ Core:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const handleSetViewMode = (mode: 'work' | 'superadmin') => {
    setViewMode(mode);
    setGlobalFilterArea('ALL'); 
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
    await db.saveUser(updatedUser);
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  // MOTOR DE VALIDACIÓN DE ESTADOS (SOLUCIÓN PERMANENTE A INCONSISTENCIAS)
  const canUserTransition = useCallback((request: RequestCard, targetStatus: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión inválida.' };

    const currentStatus = request.status;
    if (currentStatus === targetStatus) return { allowed: true };

    // Regla Maestra: SuperAdmin puede corregir cualquier flujo
    if (currentUser.role === UserRole.SUPERADMIN) return { allowed: true };

    // Regla de Seguridad: No se puede reabrir un ticket FINALIZADO sin ser SuperAdmin
    if (currentStatus === Status.FINALIZADO && targetStatus !== Status.FINALIZADO) {
        return { allowed: false, reason: 'Acción restringida: Solo el nivel SuperAdmin puede reabrir tickets finalizados para auditoría.' };
    }

    switch (activeRole) {
        case UserRole.ADMIN:
            // Admin Central: Solo mueve de Recibido a Derivación
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) return { allowed: true };
            return { allowed: false, reason: 'El rol de Administración Central solo tiene atribución para derivar tickets nuevos.' };

        case UserRole.HEAD:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado: El ticket no pertenece a su unidad de gestión.' };

            // Jefatura: Mueve de Derivación a Ejecución (Requiere Analista)
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) {
                if (!request.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un responsable técnico antes de iniciar la ejecución.' };
                return { allowed: true };
            }
            // Jefatura: Puede finalizar
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Transición no permitida para el rol de Jefatura en la fase actual.' };

        case UserRole.ANALYST:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado: Ticket fuera de su jurisdicción técnica.' };
            // Analista: Solo puede finalizar lo que está en ejecución
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Los analistas solo tienen atribución para marcar el cumplimiento final de su ejecución.' };

        default:
            return { allowed: false, reason: 'Permisos insuficientes.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `Registro formal de requerimiento en plataforma`,
        actor: `${currentUser.name} [${activeRole}]`
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser, activeRole]);

  const addLog = useCallback(async (id: string, message: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq = {
        ...req,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    // Ejecutar validación centralizada
    const { allowed, reason } = canUserTransition(req, newStatus);
    if (!allowed) throw new Error(reason);

    let logMessage = `Transición operativa a: ${newStatus}`;
    if (newStatus === Status.DERIVACION) logMessage = `Derivación formal a la unidad de ${req.area}`;
    if (newStatus === Status.EJECUCION) logMessage = `Aprobación de inicio y pase a ejecución técnica`;
    if (newStatus === Status.FINALIZADO) logMessage = `Cumplimiento de requerimiento y cierre de ticket`;

    // Lógica de reseteo SLA y campos de integridad
    const isReopening = req.status === Status.FINALIZADO && newStatus !== Status.FINALIZADO;
    const isReturningToRoot = newStatus === Status.RECIBIDO || newStatus === Status.DERIVACION;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : (isReopening ? undefined : req.finishedAt),
        isReturned: false,
        assignedAnalyst: isReturningToRoot ? undefined : req.assignedAnalyst,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: logMessage,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole, canUserTransition]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    // Solo jefaturas pueden devolver a revisión central
    if (activeRole !== UserRole.HEAD && currentUser.role !== UserRole.SUPERADMIN) {
        throw new Error("Privilegio insuficiente: Solo las jefaturas de área pueden devolver tickets a revisión central.");
    }

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined, 
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `DEVOLUCIÓN A BANDEJA CENTRAL. Motivo: ${reason}`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Personal responsable asignado: ${analystName}`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Actualización manual de campos descriptivos`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser: currentUser!,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode: handleSetViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea,
      canUserTransition
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq must be used within a SisreqProvider');
  }
  return context;
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, Filter, LayoutDashboard } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      let hasAccess = false;

      // Filtros de visibilidad por rol y departamento
      if (currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
      else if (activeRole === UserRole.ADMIN) hasAccess = true;
      else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;

      if (!hasAccess) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          req.priority.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, currentUser, activeRole]);

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');

    const req = requests.find(r => r.id === requestId);
    if (!req) return;

    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        // El motor centralizado arroja el error específico de negocio
        alert(`OPERACIÓN DENEGADA:\n${err.message}`);
    }
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-600 bg-white border-indigo-100', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-600 bg-white border-orange-100', bodyTint: 'bg-orange-50/10' },
    { title: 'En Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-600 bg-white border-amber-100', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-600 bg-white border-emerald-100', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Consola Maestra de Seguimiento";
    if (activeRole === UserRole.ADMIN) return "Bandeja Central de Administración";
    if (activeRole === UserRole.HEAD) return `Unidad de Mando: ${currentUser.area}`;
    return `Módulo Técnico: ${currentUser.area}`;
  };

  return (
    <div className="flex flex-col h-full bg-[#f8fafc]">
      <div className="px-8 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-4">
             <div className="p-2 bg-slate-50 rounded-lg border border-slate-200">
                <Filter size={14} className="text-slate-400" />
             </div>
             <h2 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-50 text-indigo-500 px-3 py-1 rounded-full text-[10px] font-black border border-indigo-100">
                {filteredRequests.length} REGISTROS
             </span>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative min-w-[350px] group">
                <Search size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Filtrar por ID, Asunto, Solicitante o Analista..." 
                    className="w-full pl-10 pr-4 py-2.5 text-xs font-bold bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[180px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-4 pr-10 py-2.5 text-xs font-bold bg-white border border-slate-200 rounded-xl appearance-none cursor-pointer outline-none hover:border-indigo-300 transition-all text-slate-600 shadow-sm"
                    >
                        <option value="ALL">Todas las Unidades</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3.5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300"><ChevronDown size={14} /></div>
                 </div>
             )}

             <div className="flex bg-slate-100 p-1 rounded-xl gap-1 border border-slate-200 shadow-inner">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`} title="Vista Kanban"><LayoutGrid size={16} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`} title="Vista Lista"><List size={16} /></button>
             </div>
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
          <div className="h-full flex px-8 py-8 gap-8 min-w-[1400px]">
              {COLUMNS_CONFIG.map((col) => {
                  const isInboxColumn = col.status === Status.RECIBIDO;
                  const canViewInbox = currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN;
                  if (isInboxColumn && !canViewInbox) return null;

                  const items = getRequestsByStatus(col.status);
                  const isOver = dragOverColumn === col.status;
                  return (
                      <div 
                          key={col.status} 
                          className={`
                              flex-1 flex flex-col min-w-[320px] max-w-[380px] transition-all duration-300 rounded-[2rem] border 
                              ${isOver ? 'bg-indigo-50 border-indigo-300 border-dashed ring-8 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                          `} 
                          onDragOver={(e) => handleDragOver(e, col.status)} 
                          onDragLeave={handleDragLeave} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className={`flex items-center justify-between px-6 py-4 mx-2 mt-2 rounded-2xl border shadow-sm shrink-0 font-black text-[10px] uppercase tracking-[0.15em] ${col.headerColor}`}>
                              <div className="flex items-center gap-3">{col.icon}{col.title}</div>
                              <span className="bg-white/80 px-2.5 py-1 rounded-lg text-[10px] text-slate-500 border border-slate-100 shadow-sm">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-3 pb-10 custom-scrollbar flex flex-col gap-2 mt-4">
                              {items.length === 0 ? (
                                  <div className={`flex-1 min-h-[220px] border-2 border-dashed rounded-[2.5rem] flex flex-col gap-4 items-center justify-center text-slate-300 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-200 bg-white shadow-xl shadow-indigo-500/5' : 'border-slate-200/40 opacity-50'}`}>
                                      <div className="p-4 bg-slate-50 rounded-full border border-slate-100">
                                          <LayoutDashboard size={32} className="opacity-20"/>
                                      </div>
                                      <span className="text-[10px] font-black uppercase tracking-widest opacity-40">{isOver ? 'LIBERAR AQUÍ' : 'Sin tickets pendientes'}</span>
                                  </div>
                              ) : (
                                  items.map(req => <RequestCard key={req.id} data={req} />)
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, 
    CheckCircle, Briefcase, Pencil, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Circle, Eye, Hash, PlayCircle
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => setSelectedRequestId(null);

  const isFinalized = data.status === Status.FINALIZADO;

  const getStatusTheme = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: 
            return { border: 'border-indigo-500', bg: 'bg-indigo-50/50', iconBg: 'bg-indigo-600', iconColor: 'text-indigo-600' };
        case Status.DERIVACION: 
            return { border: 'border-orange-500', bg: 'bg-orange-50/50', iconBg: 'bg-orange-600', iconColor: 'text-orange-600' };
        case Status.EJECUCION: 
            return { border: 'border-amber-500', bg: 'bg-amber-50/50', iconBg: 'bg-amber-600', iconColor: 'text-amber-600' };
        case Status.FINALIZADO: 
            return { border: 'border-emerald-500', bg: 'bg-emerald-50/50', iconBg: 'bg-emerald-600', iconColor: 'text-emerald-600' };
        default: 
            return { border: 'border-slate-500', bg: 'bg-slate-50/50', iconBg: 'bg-slate-600', iconColor: 'text-slate-600' };
    }
  };

  const theme = getStatusTheme(data.status);

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `NOTA DE GESTIÓN: ${newComment}`);
          setNewComment('');
      }
  }

  const handleTransition = async (targetStatus: Status, msg: string) => {
    if (confirm(msg)) {
        try {
            await updateStatus(data.id, targetStatus);
        } catch (e: any) {
            alert(`ERROR OPERATIVO:\n${e.message}`);
        }
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const formatLogDate = (timestamp: string) => {
    const logDate = new Date(timestamp);
    const now = new Date();
    const diffDays = Math.floor((now.getTime() - logDate.getTime()) / (1000 * 3600 * 24));

    if (diffDays === 0) {
        return `Hoy, ${logDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    } else if (diffDays === 1) {
        return `Ayer, ${logDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    }
    return logDate.toLocaleDateString([], { day: '2-digit', month: '2-digit', year: 'numeric' }) + ' ' + 
           logDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getTimelineConfig = (msg: string) => {
    const lower = msg.toLowerCase();
    if (lower.includes('rechazo') || lower.includes('devuelto') || lower.includes('devolución')) return { bg: 'bg-red-50', text: 'text-red-600', border: 'border-red-100', icon: <RotateCcw size={12} strokeWidth={3} /> };
    if (lower.includes('cumplimiento') || lower.includes('finalizado') || lower.includes('cerrado')) return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', icon: <CheckCircle2 size={12} strokeWidth={3} /> };
    if (lower.includes('nota de gestión:')) return { bg: 'bg-indigo-50', text: 'text-indigo-600', border: 'border-indigo-100', icon: <MessageSquare size={12} strokeWidth={3} /> };
    if (lower.includes('derivación') || lower.includes('ejecución')) return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100', icon: <ArrowRight size={12} strokeWidth={3} /> };
    if (lower.includes('registro formal')) return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', icon: <Sparkles size={12} strokeWidth={3} /> };
    return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100', icon: <Circle size={10} strokeWidth={3} /> };
  };

  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;

  const canEdit = !isFinalized && (isSuperAdmin || 
                  (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) || 
                  ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area));

  const canComment = isSuperAdmin || 
                     (activeRole === UserRole.ADMIN && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  // Selector de personal limitado estrictamente al área del ticket y usuarios activos
  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-md transition-opacity duration-300" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[3rem] shadow-[0_40px_100px_-30px_rgba(0,0,0,0.4)] w-full max-w-xl max-h-[92vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[12px] ${theme.border}`}>

        <div className={`${theme.bg} border-b border-slate-100 px-10 py-8 flex justify-between items-center shrink-0`}>
          <div className="flex items-center gap-5 min-w-0">
             <div className={`${theme.iconBg} p-4 rounded-[1.5rem] text-white shadow-xl shadow-indigo-100 shrink-0`}>
                <Eye size={24} strokeWidth={2.5} />
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2.5 mb-1.5">
                    <span className={`px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="flex items-center gap-1.5 text-[11px] text-slate-400 font-mono font-black tracking-tighter bg-white/80 px-2.5 py-1 rounded-lg border border-slate-100">
                        <Hash size={10}/>{data.id.split('-')[1].substring(0,8)}
                    </span>
                    {data.isReturned && <span className="flex items-center gap-1.5 text-[10px] bg-red-600 text-white px-3 py-1 rounded-xl font-black uppercase tracking-widest animate-pulse shadow-lg shadow-red-200"><AlertCircle size={12} /> REVISIÓN CENTRAL REQUERIDA</span>}
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={(e) => setEditTitle(e.target.value)} className="w-full text-xl font-black text-slate-900 bg-white border-2 border-indigo-200 rounded-2xl px-4 py-2 outline-none focus:ring-8 focus:ring-indigo-500/5 transition-all" autoFocus />
                ) : (
                    <h2 className="text-2xl font-black text-slate-900 leading-tight tracking-tight truncate uppercase">{data.title}</h2>
                )}
             </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isEditing && canEdit && <button onClick={() => setIsEditing(true)} className="text-slate-400 hover:text-indigo-600 p-3 rounded-2xl hover:bg-white transition-all border border-transparent hover:border-slate-100 shadow-sm hover:shadow-md" title="Editar requerimiento"><Pencil size={20}/></button>}
            <button onClick={handleClose} className="p-3 text-slate-400 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100 shadow-sm hover:shadow-md">
                <X size={24} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
            <div className="p-10 space-y-10">
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-3">
                        <Tag size={16} className={theme.iconColor}/> Detalle Técnico y Alcances
                    </label>
                    {isEditing ? (
                        <div className="space-y-5 animate-in fade-in duration-300">
                             <textarea value={editDetail} onChange={(e) => setEditDetail(e.target.value)} className="w-full h-44 bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-100 text-[14px] text-slate-700 outline-none resize-none font-bold leading-relaxed shadow-inner focus:border-indigo-400 focus:bg-white transition-all" />
                             <div className="flex justify-end gap-3">
                                <button onClick={handleCancelEdit} className="px-6 py-3 bg-slate-100 hover:bg-slate-200 text-slate-500 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all">Cancelar</button>
                                <button onClick={handleSaveEdit} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl shadow-2xl shadow-indigo-200 text-[11px] font-black flex items-center gap-3 uppercase tracking-widest transition-all"><Save size={16}/> Aplicar Cambios</button>
                             </div>
                        </div>
                    ) : (
                        <div className="bg-slate-50/70 p-8 rounded-[2.5rem] border border-slate-100 text-[16px] font-medium text-slate-700 leading-relaxed whitespace-pre-wrap shadow-inner italic border-l-4 border-l-indigo-400">
                            "{data.detail}"
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-5">
                    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-md transition-shadow">
                        <div className="text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest flex items-center gap-2.5">
                            <div className="p-1.5 bg-indigo-50 text-indigo-500 rounded-lg"><User size={12}/></div> Solicitante
                        </div>
                        <div className="text-[14px] font-black text-slate-900 uppercase tracking-tight truncate">{data.requester}</div>
                    </div>
                    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-md transition-shadow">
                        <div className="text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest flex items-center gap-2.5">
                            <div className="p-1.5 bg-indigo-50 text-indigo-500 rounded-lg"><Building size={12}/></div> Unidad Destino
                        </div>
                        <div className="text-[14px] font-black text-slate-900 uppercase tracking-tight">{data.area}</div>
                    </div>
                    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-md transition-shadow">
                        <div className="text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest flex items-center gap-2.5">
                            <div className="p-1.5 bg-indigo-50 text-indigo-500 rounded-lg"><Calendar size={12}/></div> Registro
                        </div>
                        <div className="text-[14px] font-black text-slate-900 uppercase tracking-tight font-mono">{new Date(data.createdAt).toLocaleDateString()}</div>
                    </div>
                    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-md transition-shadow">
                        <div className="text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest flex items-center gap-2.5">
                            <div className="p-1.5 bg-indigo-50 text-indigo-500 rounded-lg"><AlertCircle size={12}/></div> Urgencia
                        </div>
                        <div className={`text-[14px] font-black uppercase tracking-tight ${data.priority === 'Alta' ? 'text-red-600' : 'text-slate-800'}`}>{data.priority}</div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                    <div className="bg-slate-900 p-6 rounded-[2.5rem] border border-slate-800 flex items-center gap-6 animate-in fade-in shadow-2xl shadow-slate-300">
                        <div className="w-14 h-14 rounded-2xl bg-indigo-600 text-white flex items-center justify-center text-lg font-black shadow-xl shadow-indigo-900/40">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div className="min-w-0">
                            <div className="text-[10px] text-indigo-400 font-black uppercase tracking-[0.25em] mb-1 opacity-80">Analista Responsable</div>
                            <div className="text-lg font-black text-white truncate uppercase tracking-tight">{data.assignedAnalyst}</div>
                        </div>
                    </div>
                )}

                <div className="space-y-10 pt-8 border-t border-slate-100">
                    {canComment && (
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-3">
                                <MessageSquare size={16} className={theme.iconColor}/> Bitácora de Gestión
                            </label>
                            <div className="relative group">
                                <textarea 
                                    value={newComment} 
                                    onChange={e => setNewComment(e.target.value)} 
                                    className="w-full text-xs p-6 border-2 border-slate-100 rounded-[2rem] focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 bg-slate-50 pr-20 resize-none outline-none font-bold transition-all shadow-inner focus:bg-white" 
                                    placeholder="Ingrese observaciones, hitos de avance o requerimientos de información adicional..." 
                                    rows={3} 
                                />
                                <button 
                                    onClick={handleAddComment} 
                                    disabled={!newComment.trim()} 
                                    className="absolute right-5 bottom-5 p-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 disabled:opacity-20 transition-all shadow-xl shadow-indigo-100 active:scale-95"
                                >
                                    <Send size={20} strokeWidth={2.5}/>
                                </button>
                            </div>
                        </div>
                    )}

                    <div className="space-y-8">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-3">
                            <Clock size={16} className={theme.iconColor}/> Historial de Auditoría (SLA Trail)
                        </label>
                        <div className="space-y-6 relative before:absolute before:left-[13px] before:top-2 before:bottom-2 before:w-[3px] before:bg-slate-100">
                            {[...data.logs].reverse().map((log) => {
                                const config = getTimelineConfig(log.message);
                                return (
                                    <div key={log.id} className="flex gap-6 relative z-10 group">
                                        <div className={`shrink-0 w-7 h-7 rounded-xl border-2 shadow-sm flex items-center justify-center ${config.bg} ${config.text} ${config.border} bg-white transition-all group-hover:scale-110`}>
                                            {config.icon}
                                        </div>
                                        <div className="flex-1 min-w-0 bg-white p-5 rounded-3xl border border-slate-100 hover:border-slate-200 hover:shadow-xl hover:shadow-slate-100 transition-all">
                                            <div className="flex items-center justify-between mb-2">
                                                <span className="text-[11px] font-black text-slate-900 uppercase tracking-widest">{log.actor}</span>
                                                <span className="text-[10px] text-slate-400 font-mono font-black bg-slate-50 px-2.5 py-1 rounded-lg border border-slate-100">
                                                    {formatLogDate(log.timestamp)}
                                                </span>
                                            </div>
                                            <p className={`text-[13px] font-bold leading-snug uppercase tracking-tight ${config.text}`}>{log.message}</p>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white border-t border-slate-100 p-8 flex items-center justify-between gap-6 shrink-0 z-20">
             <button onClick={handleClose} className="px-8 py-4 text-slate-400 font-black text-[11px] uppercase tracking-[0.2em] hover:bg-slate-50 rounded-2xl transition-all">Regresar</button>
            <div className="flex items-center gap-4">
                {activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO && (
                     <button onClick={() => handleTransition(Status.DERIVACION, '¿Confirma la derivación formal a la unidad técnica correspondiente?')} className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white py-5 px-10 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-indigo-100 transition-all active:scale-95 group">
                        Confirmar Derivación <ArrowRight size={20} strokeWidth={3} className="group-hover:translate-x-1 transition-transform" />
                     </button>
                )}

                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-4">
                         {showReturnInput ? (
                             <div className="flex gap-3 items-center bg-red-50 p-3 rounded-2xl border-2 border-red-100 animate-in slide-in-from-right-10 shadow-xl">
                                <input className="w-56 text-[11px] p-4 border-2 border-red-200 rounded-xl outline-none font-black uppercase tracking-tight placeholder:text-red-300 focus:border-red-500 transition-colors shadow-inner" placeholder="Especifique el motivo..." value={returnReason} onChange={e => setReturnReason(e.target.value)} autoFocus />
                                <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-6 py-4 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-red-200 hover:bg-red-700 transition-all">Devolver</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-red-400 p-3 hover:bg-red-100 rounded-xl transition-all"><X size={22}/></button>
                             </div>
