                                    )}
                                </div>
                                <button onClick={() => handleTransition(Status.EJECUCION, '¿Confirma la validación y el inicio formal de la fase de ejecución técnica?')} className="bg-amber-500 hover:bg-amber-600 text-white py-5 px-10 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-amber-200 flex items-center gap-3 transition-all active:scale-95">
                                    <PlayCircle size={22} strokeWidth={2.5}/> Iniciar Ejecución
                                </button>
                            </>
                         )}
                    </div>
                )}

                {!isFinalized && (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button onClick={() => handleTransition(Status.FINALIZADO, '¿Declara el requerimiento como cumplido satisfactoriamente? Esta acción es definitiva e irrevocable para su rol.')} className="bg-emerald-600 hover:bg-emerald-700 text-white py-5 px-12 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-emerald-200 flex items-center gap-3 transition-all active:scale-95">
                        <CheckCircle size={22} strokeWidth={2.5}/> Finalizar Ticket
                     </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

