class DatabaseService {
    private db: IDBDatabase | null = null;
    public async init(): Promise<void> {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, DB_VERSION);
            request.onerror = () => reject(request.error);
            request.onupgradeneeded = (event) => {
                const db = (event.target as IDBOpenDBRequest).result;
                if (!db.objectStoreNames.contains(STORE_REQUESTS)) db.createObjectStore(STORE_REQUESTS, { keyPath: 'id' });
                if (!db.objectStoreNames.contains(STORE_USERS)) db.createObjectStore(STORE_USERS, { keyPath: 'id' });
            };
            request.onsuccess = async (event) => {
                this.db = (event.target as IDBOpenDBRequest).result;
                await this.seedData();
                resolve();
            };
        });
    }

    private async seedData() {
        if (!this.db) return;
        const reqCount = await this.count(STORE_REQUESTS);
        if (reqCount === 0) {
            const tx = this.db.transaction(STORE_REQUESTS, 'readwrite');
            const store = tx.objectStore(STORE_REQUESTS);
            INITIAL_REQUESTS.forEach(req => store.add(req));
        }
        const userCount = await this.count(STORE_USERS);
        if (userCount === 0) {
            const tx = this.db.transaction(STORE_USERS, 'readwrite');
            const store = tx.objectStore(STORE_USERS);
            INITIAL_USERS.forEach(user => store.add(user));
        }
    }

    private count(storeName: string): Promise<number> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("Base de datos no inicializada.");
            const tx = this.db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const request = store.count();
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }

    public async getAll<T>(storeName: string): Promise<T[]> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("Base de datos no inicializada.");
            const tx = this.db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const request = store.getAll();
            request.onsuccess = () => resolve(request.result || []);
            request.onerror = () => reject(request.error);
        });
    }

    public async save<T>(storeName: string, item: T): Promise<void> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("Base de datos no inicializada.");
            const tx = this.db.transaction(storeName, 'readwrite');
            const store = tx.objectStore(storeName);
            const request = store.put(item);
            request.onsuccess = () => resolve();
            request.onerror = () => reject(request.error);
        });
    }

    public async getRequests(): Promise<RequestCard[]> { return this.getAll<RequestCard>(STORE_REQUESTS); }
    public async saveRequest(req: RequestCard): Promise<void> { return this.save(STORE_REQUESTS, req); }
    public async getUsers(): Promise<User[]> { return this.getAll<User>(STORE_USERS); }
    public async saveUser(user: User): Promise<void> { return this.save(STORE_USERS, user); }
}

export const db = new DatabaseService();

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, UserStatus } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const generateId = (prefix: string) => `${prefix}-${Math.random().toString(36).substr(2, 6)}-${Date.now().toString(36)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests);
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Critical Failure in SISREQ Core:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const handleSetViewMode = (mode: 'work' | 'superadmin') => {
    setViewMode(mode);
    setGlobalFilterArea('ALL'); 
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
    await db.saveUser(updatedUser);
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  // MOTOR DE VALIDACIÓN DE ESTADOS (STATE MACHINE)
  const canUserTransition = useCallback((request: RequestCard, targetStatus: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no válida.' };

    const currentStatus = request.status;
    if (currentStatus === targetStatus) return { allowed: true };

    // SuperAdmin tiene bypass total para corregir errores de flujo
    if (currentUser.role === UserRole.SUPERADMIN) return { allowed: true };

    // Regla de Seguridad: No se puede reabrir un ticket FINALIZADO sin ser SuperAdmin
    if (currentStatus === Status.FINALIZADO && targetStatus !== Status.FINALIZADO) {
        return { allowed: false, reason: 'Solo el nivel de Auditoría (SuperAdmin) puede reabrir requerimientos cerrados.' };
    }

    switch (activeRole) {
        case UserRole.ADMIN:
            // Admin Central: Solo mueve de Recibido a Derivación
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) return { allowed: true };
            return { allowed: false, reason: 'Como Admin Central, solo tiene atribución para derivar requerimientos nuevos.' };

        case UserRole.HEAD:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Este requerimiento pertenece a otra unidad de gestión.' };

            // Jefatura: Derivación -> Ejecución (Requiere Analista)
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) {
                if (!request.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un responsable antes de iniciar la ejecución.' };
                return { allowed: true };
            }
            // Jefatura: Ejecución -> Finalizado
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'La transición solicitada no corresponde al flujo operativo de una Jefatura.' };

        case UserRole.ANALYST:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Ticket fuera de su área de adscripción.' };
            // Analista: Solo puede finalizar lo que ya está en ejecución
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Como analista, solo puede marcar el cumplimiento final de su ejecución.' };

        default:
            return { allowed: false, reason: 'Privilegios insuficientes.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `Apertura formal de ticket SISREQ`,
        actor: `${currentUser.name} [${activeRole}]`
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser, activeRole]);

  const addLog = useCallback(async (id: string, message: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const updatedReq = {
        ...req,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    // Validación por motor de estados
    const { allowed, reason } = canUserTransition(req, newStatus);
    if (!allowed) throw new Error(reason || "Transición bloqueada por reglas de negocio.");

    let message = `Cambio de fase operativa a ${newStatus}`;
    if (newStatus === Status.DERIVACION) message = `Derivación exitosa a la unidad de ${req.area}`;
    if (newStatus === Status.EJECUCION) message = `Aprobación de inicio y pase a ejecución técnica`;
    if (newStatus === Status.FINALIZADO) message = `Gestión concluida y ticket cerrado satisfactoriamente`;

    // Limpieza de métricas SLA si el ticket se reabre o vuelve atrás
    const isReopening = req.status === Status.FINALIZADO && newStatus !== Status.FINALIZADO;
    const isReturningToBandeja = newStatus === Status.RECIBIDO || newStatus === Status.DERIVACION;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : (isReopening ? undefined : req.finishedAt),
        isReturned: false,
        assignedAnalyst: isReturningToBandeja ? undefined : req.assignedAnalyst,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole, canUserTransition]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req) return;

    // Solo Jefaturas pueden devolver a revisión central
    if (activeRole !== UserRole.HEAD && currentUser.role !== UserRole.SUPERADMIN) {
        throw new Error("Privilegio insuficiente: Solo las jefaturas pueden devolver tickets a revisión central.");
    }

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined, 
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `RECHAZO/DEVOLUCIÓN A BANDEJA CENTRAL. Motivo: ${reason}`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Asignación de responsabilidad técnica: ${analystName}`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    if (!currentUser) return;
    const req = requests.find(r => r.id === id);
    if (!req || req.status === Status.FINALIZADO) return;

    const updatedReq = {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Actualización de información descriptiva`,
            actor: `${currentUser.name} [${activeRole}]`
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser: currentUser!,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode: handleSetViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea,
      canUserTransition
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq must be used within a SisreqProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from '../constants';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2 } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  // Lógica de arrastre sincronizada con las reglas de negocio
  const isDraggable = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return true;

    // Admin Central mueve lo Recibido
    if (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) return true;

    // Personal de área mueve sus propios tickets
    if (data.area === currentUser.area) {
        // Jefatura mueve de Derivación (si tiene analista) o de Ejecución
        if (activeRole === UserRole.HEAD) {
            if (data.status === Status.DERIVACION && !!data.assignedAnalyst) return true;
            if (data.status === Status.EJECUCION) return true;
        }
        // Analista mueve de Ejecución a Finalizado
        if (activeRole === UserRole.ANALYST && data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-2.5 relative group
            transition-all duration-200 ease-out
            shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_16px_-8px_rgba(0,0,0,0.08)]
            border border-slate-100
            border-l-[4px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'active:scale-[0.98]' : 'hover:bg-slate-50/30'}
            ${isMinimized ? 'h-[56px] py-2 px-4' : 'h-[185px] p-4'}
        `}
    >
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-2.5'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-0.5 -ml-1 text-slate-200 group-hover:text-indigo-400">
                    <GripVertical size={12} />
                </div>
            )}
            <div className="flex items-center gap-1.5">
                <span className="flex items-center gap-0.5 font-mono text-[9px] text-slate-400 font-medium uppercase tracking-tight">
                    <Hash size={9} className="opacity-30" /> {data.id.split('-')[1].substring(0, 6)}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[8px] bg-red-600 text-white px-1.5 py-0.5 rounded font-bold tracking-tight animate-pulse shadow-sm uppercase">
                        REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border shadow-none transition-colors uppercase tracking-tight ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1 text-slate-200 hover:text-slate-400 hover:bg-slate-50 rounded transition-all"
           >
               {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
           </button>
        </div>
      </div>

      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 pr-8' : 'flex flex-col'}`}>
        <h3 className={`font-semibold text-slate-700 leading-snug tracking-tight group-hover:text-indigo-500 transition-colors 
            ${isMinimized ? 'text-[11px] truncate flex-1' : 'text-[13px] mb-2 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/30 p-2.5 rounded-lg border border-slate-100/30 mb-3 overflow-hidden">
                <p className="text-[11px] text-slate-400 leading-normal line-clamp-2 font-normal italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {!isMinimized ? (
          <div className="mt-auto pt-2 border-t border-slate-100/40 flex flex-col gap-1.5 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-[9px] font-semibold text-indigo-400 uppercase tracking-tight">
                        <MapPin size={10} className="opacity-50" /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[9px] font-medium text-slate-400 uppercase tracking-tight max-w-[140px]">
                        <Building2 size={10} className="opacity-30" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[8px] font-bold border border-indigo-100" title="Responsable">
                            <UserIcon size={9} className="opacity-50" />
                            <span className="truncate max-w-[60px]">{data.assignedAnalyst.split(' ')[0]}</span>
